</table>





</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 1);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('ansys-011018', 'tr', 'ANSYS Yazılımları Duyurusu', '<div class="icerik">


    <strong>Üniversitemizin Değerli Akademik Personeli / Öğrencileri,</strong><br />
    <br />
  Bilgisayar destekli olarak mühendislik çalışmalarında analiz ve simülasyonların  yapılabildiği bir bilgisayar destekli mühendislik programı olan ANSYS  yazılımlarını temin etmiş bulunmaktayız.<br />
  <br />
  ANSYS yazılımları, Hacettepe Üniversitesi personelinin ve öğrencilerin  erişimine açık olup, network lisanslama nedeniyle sadece kampüs içerisindeki  bilgisayarlarda kullanılabilmektedir.<br />
  <br />
  <strong>ANSYS Discovery AIM v19 (Windows 64 bit) </strong>DVD kalıpları ve&nbsp; <strong>ANSYS  Electromagnetics Suite v19 (Windows 64 bit) </strong>kurulum dosyaları Yazılım  depomuzdan temin edilebilmektedir. Ayrıntılı bilgi ve kurulum kılavuzları  ilgili sayfada mevcuttur.<br />
  <br />
  Hacettepe Üniversitesi Bilgi İşlem  Portalı (<a href="https://portal.hacettepe.edu.tr/">https://portal.hacettepe.edu.tr/</a>)<br />
  <br />
  <strong>Kullanıcı adı:</strong> E-posta  kullanıcı adınız (@hacettepe.edu.tr eklemeyiniz)<br />
  <strong>Parola:</strong> Mevcut eposta  şifreniz</p>
  <p><a href="https://portal.hacettepe.edu.tr/" style="color:#006600; font-weight:bold">Portal  Sol menüden &quot;BIDB UYGULAMALARI &gt; Yazılım Deposu&quot;, iç menüden  &quot;Akademik Yazılımlar &gt; ANSYS Yazılımları&quot;</a></p>

  <p>Bilginize sunulur. Saygılarımızla. <br />
  Bilgi İşlem Daire Başkanlığı</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 2);
