INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('document-links', 'tr', 'Yararlı Dokümanlar ve Bağlantılar', '<div class="icerik">
<p>Aşağıda kullanıcılarımız için yararlı olabileceğini düşündüğümüz bazı dış   adreslere bağlantılar bulunmaktadır. Bu bağlantıların sürekliliği, geçerliliği   ve güncelliği tarafımızdan zaman zaman kontrol edilse de, oluşabilecek   kopukluklar ve sitelerin geçerliliğini kaybetmesi gibi durumların da   oluşabileceğini kullaıcılarımızın bilgilerine sunarız.    
<p>Burada verilen bağlantılara zaman içinde yeni eklemeler / çıkarımlar   yapılabilmektedir. </p>
<p><STRONG>Yararlı Bağlantı''lar </STRONG></p>
<UL>
  <LI>ULAKBİM, Ulusal Akademik Ağ ve Bilgi Merkezi: <A href="http://www.ulakbim.gov.tr/" target="_new">www.ulakbim.gov.tr</A> <BR>
  </LI>
  <LI>Türk Anti-Spam Organizasyonu: <A href="http://www.spam.org.tr/" target="_new">www.spam.org.tr</A> <BR>
  </LI>
  <LI>Ulaknet''ten Türkçe Güvenlik Dokümanları: <A href="http://csirt.ulakbim.gov.tr/dokumanlar/" target="_new">csirt.ulakbim.gov.tr/dokumanlar</A> <BR>
  </LI>
  <LI>Ulaknet''ten Türkçe Güvenlik Dokümanları: <A href="http://csirt.ulakbim.gov.tr/dokumanlar/" target="_new">csirt.ulakbim.gov.tr/dokumanlar</A> </LI>
</UL>


</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 11);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('hardware', 'tr', 'Donanım', '<div class="icerik">



<p align="justify">Hacettepe Üniversitesi Bilgi İşlem Dairesi’nin başta ağ cihazları ve fiber kablolama olmak üzere bilişim hizmetleri alanında hizmet vermeye yönelik alt yapı olanakları mevcuttur.</p>
<p align="justify">Beytepe  Yerleşkemizde çalışan  1  adet  router,  yedekli  çalışan  iki  ana  omurga,  57  adet yarı omurga 3. seviye ağ anahtarlama cihazı, 509 adet 2. seviye ağ anahtarlama cihazı ile 1761 adet WIFI cihazı ve WIFI yönetimi için 5 adet merkezi kontrol cihazı, 56 tane merkezi kontrol cihazından bağımsız WIFI cihazı mevcuttur.  </p>

<p align="justify">Sihhiye kampusümüzde çalışan bir adet “router”, yedekli ana omurga, 1 adet bant genişliği yönetim cihazı ,14 adet 3. seviye ağ anahtarlama cihazı, 174 adet 2.seviye ağ anahtarlama cihazı ile 274 adet Wi-Fi cihazı mevcuttur.</p>
<p align="justify">Ağ sistemimizin güvenliği için kampüs ve sunucular önünde yedekli güvenlik duvarı sistemi kullanılmaktadır. Sıhhiye kampüsümüzün güvenliği için yedekli güvenlik duvarı sistemi ve URL filtreleme sistemleri kullanılmaktadır.</p>





</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 12);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('notice-110520', 'tr', 'Kampüs İçerisinden Ulaşılabilen Uygulamalar', '<div class="icerik">

<p>Değerli Hacettepeliler,<br />
Uzaktan eğitim s&uuml;recinde &ouml;ğretim &uuml;yelerimiz ve &ouml;ğrencilerimizin yazılımlara daha rahat ulaşabilmeleri i&ccedil;in &ouml;nemli bir duyuruyu sizlere paylaşmak isteriz.</p>



<p>Kamp&uuml;s i&ccedil;erisinden ulaşılabilen aşağıdaki listedeki uygulamalar VPN servisi &uuml;zerinden erişime a&ccedil;ılmıştır. Bu &ccedil;er&ccedil;evede,</p>

<ul>
	<li>ARCGIS</li>
	<li>SPSS</li>
	<li>Matlab Akademik &amp; Classroom</li>
	
	<li>Simapro</li>
</ul>

<p>yazılımların kamp&uuml;s dışında kullanılabilmesi i&ccedil;in VPN bağlantısının sağlanması gerekmektedir.<br />
<strong>VPN yazılımının indirilmesi ve kurulum kılavuzu i&ccedil;in <a href="http://www.bidb.hacettepe.edu.tr/tr/VPN" target="_blank">http://www.bidb.hacettepe.edu.tr/tr/VPN</a> adresini ziyaret ediniz.</strong></p>



</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 13);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('notice-121120', 'tr', 'Güvenli E-Posta Bilgilendirme Metni', '<div class="icerik">

<p>T.C. Cumhurbaşkanlığı, Dijital Dönüşüm Ofisi, 24 Temmuz 2020 tarihli Bilgi ve İletişim Güvenliği Rehberi(<a href="https://cbddo.gov.tr/SharedFolderServer/Genel/File/bg_rehber.pdf" target="_blank">https://cbddo.gov.tr/SharedFolderServer/Genel/File/bg_rehber.pdf</a>), 3.1.4.8 tedbir maddesinde belirtilen;<br />
<br />
&quot;Sahte ya da bütünlüğü bozulmuş e-postaların geçerli etki alanlarına sızma ihtimalini azaltmak için SPF, DKIM vb. teknoloji ve standartlar kullanılmalıdır.&quot;<br />
ilkesi gereği, güvenli e-posta alışverişi yapabilmek için gerekli çalışmalar başkanlıgımız tarafından yapılmıştır.<br />
<br />
Bu kapsamda diger kurumların e-posta haberleşmelerini sağlıklı yapabilmeleri için kendi alan adı sunucularında PTR, SPF, DKIM alan adı kayıtlarını ve DMARC politikalarını devreye almaları/ güncellemeleri tavsiye edilmektedir.<br />
<br />
DNS kayıtlarında yukarıda bahsi geçen kayıtları güncellemeyen/yayımlamayan kurumlar ile gerçekleşen e-posta haberleşmesi kurumumuz politikaları geregi şüpheli/istenmeyen (SPAM) e-posta olarak işaretlenecektir.<br />
<br />
Önemle bilginize.</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 14);
INSERT INTO belge (sayfa_id, ad, adres, tur, sira) SELECT id, 'https://cbddo.gov.tr/SharedFolderServer/Genel/File/bg_rehber.pdf', 'https://cbddo.gov.tr/SharedFolderServer/Genel/File/bg_rehber.pdf', 'PDF', 0 FROM sayfa WHERE slug = 'notice-121120' AND dil = 'tr';
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('notice-iskur-280225', 'tr', 'İŞKUR Gençlik Programı, İş Sağlığı ve Güvenliği Eğitimi', '<div class="icerik">
   
    <p><strong>İŞKUR Gençlik Programı, İş Sağlığı ve Güvenliği Eğitimi</strong></p>

<p>İŞKUR Gençlik Programı kapsamında programa katılmaya hak kazanan öğrencilerimizin   <strong>5 Mart 2025 </strong>günü saat <strong>10.00-12.00</strong> arası Üniversitemiz <strong>İş Sağlığı ve Güvenliği Koordinatörlüğü </strong>tarafından verilecek online eğitime katılmaları gerekmektedir.</p>

<p><strong>Katılım Linki: <a href="https://teams.microsoft.com/l/meetup-join/19%3ameeting_OWVkMmE2Y2ItNGJkMy00YTg5LWEyOTMtNzMxNjAzZTBhZWI3%40thread.v2/0?context=%7b%22Tid%22%3a%22fda4d358-3750-4b5b-9588-c0294ccf291e%22%2c%22Oid%22%3a%22f09f3a94-f6ad-4014-9fe0-50a6d165c11d%22%7d" target="_blank">https://teams.microsoft.com/l/meetup-join/19%3ameeting_OWVkMmE2Y2ItNGJkMy00YTg5LWEyOTMtNzMxNjAzZTBhZWI3%40thread.v2/0?context=%7b%22Tid%22%3a%22fda4d358-3750-4b5b-9588-c0294ccf291e%22%2c%22Oid%22%3a%22f09f3a94-f6ad-4014-9fe0-50a6d165c11d%22%7d</a></strong></p>

</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 15);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('notice-050416', 'tr', 'Duyurular', '<div class="icerik">
<p><b>Kişisel web sayfaları için ev dizini açılım kontrolü (FTP)</b></p>
 
<p>Kişisel web sayfaları için sunucuya ev dizini açılımı sunucuya FTP ile bağlandıklarında gerçekleşmektedir.<br>
FTP ile alana bağlandıktan sonra web sayfaları taşıması için public_html klasörü elle oluşturulmalıdır. Ayrıntılı bilgiye <a href="/hizmetlerweb/kisisel.shtml">http://www.bidb.hacettepe.edu.tr/hizmetlerweb/kisisel.shtml</a> sayfasından ulaşabilirsiniz.</p>
 
 
<p>Karşılaştığınız sorunlarını <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> adresine eposta ile bildirebilirsiniz.</p>
 
<p>Bilgilerinize sunarız.</p>
 
<p>HÜ BİDB Sistem Grubu</p>

</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 16);
