INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('email-account', 'tr', 'Yeni E-posta Açma', '<div class="icerik">
<p>Kişisel e-posta Hesabı Almak için:</p>
<ul>
  <li><strong>Yeni kayıt yaptıran ön lisans, lisans öğrencilerimiz için;</strong></li>
</ul>
<p>Kayıt yaptırdıkları tarihten sonra Bilgi İşlem Daire Başkanlığı tarafından @hacettepe.edu.tr uzantılı kurumsal elektronik posta hesapları otomatik açılarak, BİLSİS&rsquo;te (Öğrenci Bilgi Sistemi) kayıtlı cep telefonu numarasına veya e-posta adresine mesaj olarak gönderilmektedir.<br>
  Mesajın ulaşmaması durumunda; Bilgi İşlem Daire Başkanlığı Portal sayfasından &ldquo;Kullanıcı Adımı Unuttum&rdquo; ve &ldquo;Şifremi Unuttum&rdquo; butonlarını kullanarak hesap bilgilerine ulaşmaları gerekmektedir.</p>
<ul>
  <li><strong>Hacettepe Üniversitesi Yüksek Lisans ve Doktora Öğrencilerimiz için;</strong></li>
</ul>
<p>Kayıt yaptırdıkları tarihten sonra Bilgi İşlem Daire Başkanlığı tarafından @hacettepe.edu.tr uzantılı kurumsal elektronik posta hesapları otomatik açılarak, PRENS&rsquo;te (Enstitü Öğrenci Bilgi Sistemi) kayıtlı cep telefonu numarasına veya e-posta adresine mesaj olarak gönderilmektedir.<br>
  Mesajın ulaşmaması durumunda; Bilgi İşlem Daire Başkanlığı Portal sayfasından &ldquo;Kullanıcı Adımı Unuttum&rdquo; ve &ldquo;Şifremi Unuttum&rdquo; butonlarını kullanarak hesap bilgilerine ulaşmaları gerekmektedir.</p>
<ul>
  <li><strong>Hacettepe Üniversitesi &ldquo;Akademik&rdquo; ve &ldquo;İdari&rdquo; personelimiz;</strong></li>
</ul>
<p>Elektronik posta hesabı almak isteyen akademik/idari personelimizin 0.312 297 62 62 telefon numarasından Çağrı Merkezi ile iletişime geçmesi gerekmektedir.</p>

<p> <STRONG>Kurumsal e-posta Hesabı  Almak için:</STRONG></p>
<p> Hacettepe Üniversitesi  bünyesinde, fakülte, enstitü, bölüm, birim, üniversite ile ilgili bir topluluk,  proje grubu, organizasyon vb. bir oluşum için ayrı bir e-posta hesabı almak  mümkündür. Bunun için bağlı bulunduğunuz makamın (dekan, bölüm başkanı,  müdürlük, vb.) yönetiminden dairemize yazılı bir istekte bulunulması  gerekmektedir. İstekte, bu hesabın açık olarak ne amaçla açılacağı, kimin  sorumlu olacağı ve ne kadar süre ile açık kalacağı belirtilmelidir. </p>

<p> <STRONG>Mezun E-posta Hesabı  Almak için:</STRONG></p>
<p>
  Hacettepe Üniversitesi Elektronik Posta Sistemlerinde kullanıcılarımızın daha verimli ve etkili bir şekilde iletişim kurmasına yardımcı olmak amacıyla iyileştirme ve geliştirme çalışmaları yapılmış, 11 Mayıs 2022 tarihinden itibaren <strong>yeni e-posta sistemi (Microsoft Exchange)</strong> kullanılmaya başlanmıştır.</p><p>
  Mezun öğrencilerimizin Üniversitemize bağlılıkları göz önünde bulundurularak, yürürlüğe giren <strong><em>8.12.2022 tarih ve 2022-000 sayılı Senato kararına</em></strong> istinaden Hacettepe Üniversitesi mezunlarının Mezunlar Derneği üyesi olmadan kurumsal e-posta almalarına olanak sağlanmıştır. </p>
  <p><a href="/tr/alumni-email">Detaylı Bilgi İçin tıklayınız</a></p>


<p><STRONG>İlgili formlar için<a href="/tr/formlar/"> tıklayınız.</a></STRONG></p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 20);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('email-migration', 'tr', 'Hacettepe Üniversitesi Yeni E-posta Hizmeti (Microsoft Exchange Servisi) Hakkında Bilgilendirme', '<div class="icerik">


        <p class="mt-0"><strong>Kurulum Ayarları</strong></p>
    

    <p><a href="/dosyalar/yenimail/web_arayuz_giris.pdf" target="_blank">Mail Arayüzü Üzerinden Giriş</a></p>
       <p><a href="/dosyalar/yenimail/outlook_kurulum.pdf" target="_blank">Outlook Mail Hesabı Ayarları</a></p>   
 <p><a href="/dosyalar/yenimail/android_outlook_191125.pdf" target="_blank">Android Cihazlarda Outlook Mail Hesabı Ayarları</a></p>
        <p><a href="/dosyalar/yenimail/Android_posta_kurulum_250522.pdf" target="_blank">Android Mail Hesabı Ayarları</a></p>
        <p><a href="/dosyalar/yenimail/ios_kurulum_250522.pdf" target="_blank">IOS Mail Hesabı Ayarları</a></p>
        <p><a href="/dosyalar/yenimail/MACOSkurulum2.pdf" target="_blank">MacOS Mail Hesabı Ayarları</a></p>


        <p></p>


<p><strong>Neden e-posta servisini değiştiriyoruz?</strong></p>
 <p>Üniversitemizde kullanmış olduğumuz e-posta sistemini:</p>
<ul>
  <li>Kullanıcı yönetimini sağlıklı ve güvenli yapabilmek,</li>
  <li>Gelişen teknolojiye ayak uydurabilmek,</li>
  <li>Günümüz siber güvenlik ihtiyaçlarına ayak uydurabilmek,</li>
  <li>Daha güvenilir ve daha kullanıcı dostu hizmet sağlayabilmek,</li>
  <li>Olası sorunlarda zaman ve maddi açıdan ekonomik çözümleri bulabilmek,</li>
  <li>Geçmişten gelen veri kirliliğini belirli bir oranda temizlemek</li>
</ul>
<p>Amacıyla değiştiriyoruz.</p>

<p><strong>Yapılacak bu değişiklikle beraber:</strong></p>
<ul>
  <li>Microsoft&rsquo;un Exchange servisi kullanılacaktır.</li>
  <li>E-postalarınız yeni sisteme taşınmış olacaktır.</li>
  <li>Her kullanıcıya epostalarını saklayabilecekleri alan <span class="text-danger">5 GB</span> olarak belirlenmiştir.</li>
  <li>Hacettepe Üniversitesi öğrencileri için  <span class="text-danger">100 GB Onedrive</span> bulut alanı </li>
  <li>Kullanıcı bilgileri ve e-postalar Hacettepe Bilgi İşlem Daire Başkanlığı&rsquo;mızdaki sunucularımızda tutulacaktır. </li>
  <li>Yeni sistemle beraber sunmuş olduğumuz diğer Microsoft hizmetleri daha uyumlu çalışabilecektir. </li>
  <li>Eski sistemde eposta kullanıcı adı ve şifrenizle kullanabildiğiniz hizmetleri yeni sistemde de kullanmaya devam edebileceksiniz. (Kablosuz internet hizmeti, yazilimdeposu ..vb)</li>
</ul>

<div class="uyari alert alert-warning">
  <p>Uyarı-1: Her kullanıcı 24 saatlik süre içerisinde dışarıya maksimum<strong> </strong>50 mail gönderebilecektir.<br>
  Uyarı-2: Her kullanıcının bir mailde gönderebileceği maksimum e-posta büyüklüğü <strong>25 MB</strong> olacaktır.<br>
  Uyarı-3: Her bir mailde mailin iletilebileceği <strong>alıcı sayısı 30</strong> olacaktır.</p>
</div>



<p><strong>Yeni e-posta sistemini kullanabilmeniz için,</strong></p>
<ol>
  <li><a href="https://portal.hacettepe.edu.tr" target="_blank">portal.hacettepe.edu.tr</a> adresine gidiniz.<strong></strong></li>

  <li>Bilgi güncelleme işlemini yapınız. <a href="https://portal.hacettepe.edu.tr/hesap/bilgiguncelleme" target="_blank">(Bilgi Güncelleme)</a>
  <ul>
    <li>Karşınıza çıkan ekranda Bilgi Güncelleme butonuna tıklayınız. Mevcut eposta kullanıcı adınız ve şifrenizi kullanarak giriş yapınız.</li>
    <li>Bilgi güncelleme ekranındaki boşlukları eksiksiz ve hatasız doldurunuz.</li>
    <li>E-posta Kullanıcı Sözleşmesini onaylayınız.</li>
    <li class="text-danger">Bilgi güncelleme ekranında alınan bilgiler MERNİS üzerinden doğrulanmak amacıyla istenmektedir. Sistemimize kaydedilmemektedir.</li>
    <li>
      <div class="embed-responsive embed-responsive-16by9 mb-3">
  <iframe class="embed-responsive-item" src="https://www.youtube.com/embed/1q2ingOIwEY" allowfullscreen></iframe>
</div>
    </li>
    <li><a href="/dosyalar/BilgiGuncellemeDokuman.pdf" target="_blank"><strong>Bilgi Güncelleme Dokümanı (.PDF)</strong></a></li>
  </ul>
  </li>
  <li>Şifre güncelleme işlemini yapınız.
    <ul>
      <li>Bu sayfada eski şifrenizi girdikten sonra yeni şifrenizi belirleyiniz. </li>
  <li>Yeni şifrenizin; en az 8 karakter olmasına, en az 1 büyük harf, 1 küçük harf, 1 rakam ve 1 özel karakter içermesine, Türkçe karakter kullanılmamasına dikkat edilmelidir.</li>
  <li>
      <div class="embed-responsive embed-responsive-16by9 mb-3">
  <iframe class="embed-responsive-item" src="https://www.youtube.com/embed/CmwHF20CFrw" allowfullscreen></iframe>
</div>
    </li>

    <li><a href="/dosyalar/SifreGuncelleme.pdf" target="_blank"><strong>Şifre Güncelleme Dokümanı (.PDF)</strong></a></li>

    </ul>
  </li>
  
  <li><strong><a href="https://posta.hacettepe.edu.tr" target="_blank">posta.hacettepe.edu.tr</a></strong> adresine giriş yaparak yeni eposta servisini kullanmaya başlayabilirsiniz.</li>
  <li>Yeni eposta sistemi aktif şekilde kullanılmaya başlandıktan sonra geçiş süreci tamamlanana kadar kullanıcılarımız <a href="https://eskiposta.hacettepe.edu.tr" target="_blank">eskiposta.hacettepe.edu.tr</a> adresinden eski eposta kutularına erişilebilecektir. <a href="https://eskiposta.hacettepe.edu.tr" target="_blank">eskiposta.hacettepe.edu.tr</a>  adresi yeni e-posta sisteminin devreye alınması ile aktif hale gelecektir.</li>
</ol>

<div class="uyari alert alert-warning">
<p>Uyarı-1: Her kullanıcı 5 dk lık süre içerisinde dışarıya maksimum 200 mail gönderebilecektir.<br>
  Uyarı-2: Şifrenizi kullandığınız son 3 şifrenizden farklı yapmanız sizin güvenliğiniz için önemlidir.<br>
  Uyarı-3: Bilgi İşlem personeli dâhil hiç kimse sizden şahsi şifrenizi paylaşmanızı istemez. Bu sebeple şifrenizi kimseyle paylaşmayınız.<br>
  Uyarı-4: Şifrenizi en fazla 90 günde bir değiştirilmesi zorunludur.<br>
  Uyarı-5: Adımları doğru tamamladıktan sonra yine hata alırsanız lütfen yardım için Çağrı Merkezi ile iletişime geçiniz. 0 312 297 6262</p>
</div>





    


<p></p>
<p><a href="/dosyalar/EskiEpostaYedekAlmaIslemleri.pdf" target="_blank">Eski E-Posta Yedek Alma İşlemleri</a></p>
<p><a href="/tr/email-backup-video">Eski E-Posta Yedek Alma İşlemleri (Videolu Anlatım)</a></p>
<p><a href="/dosyalar/epostayonergesi_300120.pdf" target="_blank">HÜ E-Posta Yönergesi</a></p>


</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 21);
