INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('about', 'tr', 'Genel Tanıtım', '<div class="icerik">

    <p align="justify"><strong><u>Ağ  Birimi (Beytepe):</u></strong> Yerel ağın kurulumu, mevcut ağın  yönetimi, denetimini yapar  ve ağın  geleceği ile ilgili projeleri üretir, kullanıcılara internet kullanımı hizmeti  verilmesi için gerekli altyapı, donanım, yazılım ve bilgi desteği sağlar. </p>
    <p align="justify"><strong><u>Ağ ve  Sistem Birimi (Sıhhiye):</u></strong> Yerel ağın kurulumu, mevcut  ağın yönetimi, denetimini yapar  ve ağın  geleceği ile ilgili projeleri üretir, kullanıcılara internet kullanımı hizmeti  verilmesi için gerekli altyapı, donanım, yazılım ve bilgi desteği sağlar.  Başkanlığımızın ev sahipliği yaptığı tüm sunucu bilgisayarları ve temel  internet servislerini (DNS, FTP, WEB, E-POSTA, WEBMAIL, PROXY, vb.) 5651 sayılı  İnternet Ortamında Yapılan Yayınların Düzenlenmesi ve Bu Yayınlar Yoluyla  İşlenen Suçlarla Mücadele Edilmesi Hakkında Kanun, Telekomünikasyon Kurumu  Tarafından Erişim Sağlayıcılara ve Yer Sağlayıcılara Faaliyet Belgesi  Verilmesine İlişkin Usul ve Esaslar Hakkında Yönetmelik, İnternet Ortamında  Yapılan Yayınların Düzenlenmesine Dair Usul ve Esaslar Hakkında Yönetmelik  çerçevesinde işletir, günceller ve yedeklemesini yapar.</p>
    <p align="justify"><strong><u>Sistem  ve Güvenlik Birimi (Beytepe):</u></strong> Başkanlığımızın ev  sahipliği yaptığı tüm sunucu bilgisayarları ve temel internet servislerini  (DNS, FTP, WEB, E-POSTA, WEBMAIL, PROXY, vb.) 5651 sayılı İnternet Ortamında  Yapılan Yayınların Düzenlenmesi ve Bu Yayınlar Yoluyla İşlenen Suçlarla  Mücadele Edilmesi Hakkında Kanun, Telekomünikasyon Kurumu Tarafından Erişim  Sağlayıcılara ve Yer Sağlayıcılara Faaliyet Belgesi Verilmesine İlişkin Usul ve  Esaslar Hakkında Yönetmelik, İnternet Ortamında Yapılan Yayınların  Düzenlenmesine Dair Usul ve Esaslar Hakkında Yönetmelik çerçevesinde işletir,  günceller ve yedeklemesini yapar. Sistem odasının ve  Kesintisiz Güç Kaynağı odasının güvenliğini  sağlar.</p>
    <p align="justify"><strong><u>Sistem  Yazılımları Birimi:</u></strong> Yönetim sistemleri çerçevesinde çalışan uygulamaların, veritabanı ve  uygulama sunucularının bakım, yedekleme ve idaresi ile bu sistemlerin Bilgi  İşlem Dairesi tarafından idare edilen diğer sistemlerle eş güdümünü sağlar.</p>
    <p align="justify"><strong><u>Yazılım  Geliştirme Birimi:</u></strong><u> </u>Üniversitemiz bünyesindeki  birimlerimizin işlerini bilgisayar ortamına taşımak ve toplanan veriler  üzerinden istenen raporları üretebilmek amacı ile iletilen yazılım  ihtiyaçlarını değerlendirilerek en uygun çözüm yöntemini belirler. Gerek idari  gerekse akademik işler sırasında ortaya çıkan yazılım ihtiyacının karşılanması  ve gerek görüldüğü takdirde mevcuttaki diğer yazılımlarla entegrasyonun  sağlanması için ihtiyaçları değerlendirir, analiz eder ve çözüm önerileri  sunar.</p>
    <p align="justify"><strong><u>BYS ve Bireysel  İşlemler Birimi:</u></strong><u> </u>Üniversitemizin Yönetim  Sistemleri <strong>BYS</strong> (Belge Yönetim Sistemi), <strong>Bİ</strong> (Bireysel İşlemler) sistemlerini işletme ve bu sistemleri kullanan  personelimize son kullanıcı desteği verme konusunda faaliyet göstermektedir. Elektronik-İmza için  gerekli Nitelikli Elektronik Sertifika (NES) ilk başvurusunu üniversite  personeli adına TÜBİTAK KAMUSM (Kamu Sertifikasyon Merkezi)’ne yapar, KAMUSM ye  başvuru ile başlayıp NES’ nın ilgili personele iletilmesine kadar geçen süreci  yöneterek kayıp, çalıntı, iptal, yenileme durumlarında ilgili üniversite  personeline destek olur, Üniversite personeline Elektronik-İmza uygulamalarında  ihtiyaç duyulacak kurulumlar için destek olur, Elektronik-İmza işleyişi  hakkında Üniversite personelini web sayfası ve&nbsp; e-posta yoluyla  bilgilendirir, Bilgi İşlem Daire Başkanlığı ile Kamu Sertifikasyon Merkezi  (Kamu SM) arasındaki yazışmalar, idari işlemler ve teknik konularda  koordinasyonu sağlar.</p>
    <p align="justify"><strong><u>İdari ve Mali  İşler Birimi:</u></strong>Başkanlığımızın bir sonraki yıla ilişkin tahmini bütçesini hazırlar. Harcama yetkisinde olan bütçe tertiplerine ilişkin satın almaları yapar. İlk altı aylık ve yıllık Birim Faaliyet Raporlarını hazırlar. 5 yıllık stratejik planını hazırlar. Yıl içerisinde 3’er aylık dilimler halinde birim izleme raporunu hazırlar. Birim Taşınır Kayıt Kontrol Sistemini yöneterek taşınır girişi, çıkışı, hurdaya ayırma gibi işlemlerini ve birim içi demirbaş zimmetlerini yapar. Başkanlık içi bakım ve onarım işlerini koordine eder. Belirli dönemlerde Başkanlık Birimlerinin ihtiyaçlarını toplayarak ihtiyaç listelerini oluşturur. Yönetim tarafından istenen raporları hazırlar ve sunar.</p>
    <p align="justify"><strong><u>İnsan  Kaynakları Birimi:</u></strong> Üniversitemizin İnsan Kaynakları  Yönetim Sistemini (İKYS) işletir ve Personel Dairesi Başkanlığındaki personel  ve tahakkuk kullanıcılarına son kullanıcı desteği verir,<strong> </strong>İnsan Kaynakları Yönetim Sisteminde (İKYS) daha önceden ön  görülmemiş Liste, Rapor ve İstatistiksel Tabloların oluşturulmasını sağlar,  Üniversitemizin tüm çalışanlarının bordrolarını (Maaş, Maaş Farkları, Döner  Sermaye, Nöbet, Ekders, İkramiye, İkramiye Farkı) yasal ekleri ile birlikte  tahakkuk müdürlüklerine hazırlar ve kişiye verilen bordronun e-posta yoluyla dağıtımını  yapar.</p>
    <p align="justify"><strong><u>Kullanıcı  Destek Birimi :</u></strong> 
Üniversitemiz bünyesinde demirbaş kaydı bulunan bilgisayar ve çevre birimlerinin bakım ve onarımını yapar, onarılamayacak durumda donanım arızası olanları rapor eder, bilgisayarda mevcut bulunan ek donanımların sisteme tanıtılmasını sağlar. 
<br>Bu birim içerisinde bulunan "Çağrı Merkezi" ise elektronik posta hesaplarının açılması, şifre değişikliği talebi ve e-posta hesaplarına ilişkin telefon desteği sağlar. Sorun Bildirim ve Destek Sistemi aracılığı ile gelen talepleri yanıtlar. Üniversitemiz birimlerinin yaptığı etkinlikler (konferans, kongre) için teknik destek sağlar (bilgisayar, yazıcı, projeksiyon cihazı gibi donanımların kurulumu v.b.), Başkanlığa telefon aracılığı ile ulaşan yardım taleplerini karşılar. 
<br>İnternet üzerinden hizmet veren lisanslı ve ücretsiz programların bulunduğu Yazılım Deposu ara yüzünün işletilmesi ve güncellenmesini yapar.
   


 <p align="justify"><strong><u>Web  Birimi:</u></strong> Hacettepe Üniversitesi web sayfasının yapılandırılması ve  güncellenmesi, Akademik/İdari Birimler, Öğrenci Toplulukları ve  Organizasyonlara yönelik web sayfası oluşturulması, Akademik/İdari Personel ve  Öğrenci kişisel web sayfalarına teknik destek sağlanması görev yürütür.</p>
    <p align="justify"><strong><u>Bilgisayar  Laboratuvarları:</u></strong> Üniversitemiz Sıhhiye Kampüsünde hizmet veren 75 bilgisayarlık laboratuvarın işletilmesini sağlamaktadır.</p>

</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 26);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('security', 'tr', 'Virüsler ve Güvenlik Önerileri', '<div class="icerik">

<p><STRONG>Virüs</STRONG></p>
Bilgisayar virüsleri, genellikle bilgisayara zarar vermek,   çalışmasını zorlaştırmak ya da kullanıcının çalışmasına engel olmak amacıyla   yazılmış program parçalarıdır. Bu programlar tek başına durabileceği gibi,   genellikle bilgisayarda bulunan başka amaçlı bir programın içine yerleşerek   çalışırlar. Virüsler, bir kere çalışmayı başardıklarında kendilerini başka   dosyalara da kopyalamaya çalışırlar. Bazı dosyalar, işletim sistemleri   tarafından otomatik olarak ve geri planda çalıştırıldıkları için virüslü bir   dosya barındıran bir bilgisayar bu dosyayı çalıştırabilir ve virüs aktif hale   gelince kendini diğer dosyalara da kopyalar. Hatta virüslü bir bilgisayar,   kendisine bağlı farklı medyalarda (disketler, yazılabilir flash diskler, yazma   hakkı bulunan ağ paylaşımlı klasörler, vs.) bulunan dosyaları da   virüslendirebilir.
<p>Virüsler, aktif hale gelmek için "çalıştırılmak" zorundadır. Başka bilinen   bir işlevi olan, ancak virüs bulaşmış bir program çalıştırıldığında içine   yerleşik olan virüs de aktif hale gelmiş olur. Yaygın inanışın aksine, virüslü   bir disket, flash bellek, CD vb. bilgisayara yerleştirildiğinde -eğer otomatik   çalıştırılan (auto-run) bir dosya yoksa- bilgisayara virüs bulaşmaz. Virüsün   aktif hale gelmesi için virüslü dosyanın elle ya da işletim sistemi tarafından   çalıştırılması gerekir. </p>
<p>Virüs bulaşabilen dosyalar ilk zamanlarda sadece "program" dosyaları idi.   Yani genellikle sonu ".exe, .com, .pif" ile biten dosyalardı. Ancak yazılım   teknolojisinin gelişimi, "çalıştırılabilen" dosya tiplerinin artması ve işletim   sistemlerinin karmaşıklaşması ile birlikte potansiyel tehlike oluşturan dosya   tipleri de arttı. Bir zamanlar sadece "metin" dosyası olarak bilinen ".doc"   uzantılı dosyalar, ofis yazılımlarının ilerlemesi ile içine "çalıştırılabilen"   programcıkların (makrolar) da yerleştirilebildiği karmaşık dosyalara dönüştü.   Yine, sadece "resim" içerdiği için masum görülen ".gif" uzantılı dosyalar,   popüler işletim sistemlerinin açıkları kullanılarak birer potansiyel virüs   kaynağı haline gelebildiler. </p>
<p>Şu anda, ekran koruyuculardan, masum dökümanlara kadar birçok dosya, "virüs   bulaşabilir ve bulaştırabilir" bir hale gelmiştir. </p>
<p>Virüsler Internet''ten indirilen -kaynağı şüpheli- dosyalardan, virüslü   e-posta eklentilerinden ve dışarıdan bilgisayara takılan disket, flash bellek,   CD gibi ortamlarda bulunan virüslü dosyalardan bilgisayara gelirler. </p>
<p>Virüslü bir bilgisayar antivirüs programları ile taratılarak tespit   edilebilir. Kullanıcı, bilgisayarının çalışmasındaki aşırı yavaşlamadan da   şüphelenebilir. Bazı virüsler için, antivirüs üretici firmalar Internet''ten   indirilip çalıştırılabilen küçük ve sadece o virüs tipine etkili   tarayıcı/temizleyici programlar yayınlarlar. Ancak bunun bir garantisi yoktur ve   virüs bilgisayarı yeniden kurana kadar temizlenemeyebilir. Hatta bazı yeni nesil   virüsler bilgisayara girip uzun süre kendilerini gizleyerek kuluçkaya yatarlar.   Bunlar uygun bir zamanda aktif hale geçip, bilgisayara gerekli zararı verip,   hatta belki kullanıcıya ait verileri (şifreler, vs.) merkezine yollayıp   kendilerini imha edebilirler ve izlerini tamamen kaybettirebilirler. Bu nedenle   antivirüsler de bu noktada çaresiz kalabilirler. </p>
<p>Yukarıda anılan virüslere "dosya virüsleri" adı verilir. Bunlardan ayrı   olarak disklerin işletim sistemlerini yüklerken ilk başvurdukları bölge olan   "boot sector"e yerleşen virüsler de mevcuttur. İşlevleri, görevleri ve davranış   biçimleri diğer virüslerle aynıdır. Farklı olan bunların diskte daha farklı   alanlarda kendilerini saklamalarındadır. Ancak bunların yaygınlıkları daha   azdır. </p>
<p><STRONG>Worm (Solucan)</STRONG></p>
Worm''lar genellikle kullanılan işletim sistemlerinin   yazılımındaki hata ve açıkları kullanarak ağ üzerinden bilgisayara girebilen   zararlı yazılımlardır. Virüs''lerle benzer işlevleri vardır, ancak bulaşmak için   kullanıcı tarafından çalıştırılması gereken programlar değillerdir. Diğer bir   deyişle, worm''lar bilgisayar ağını tararlar ve güvenlik açığı buldukları   bilgisayarlara hiç bir kullanıcı aktivitesi olmadan girerler. Yeni kurulmuş,   ancak gerekli yamaları yapılmamış bir bilgisayar, Internet ağına bağlandığı anda   (kablosunun takılması ve gerekli IP ayarlarının yapılması) worm kapabilir.
<p>Worm''lardan korunmanın en iyi yolu, bilgisayarı ilk kurarken işletim   sistemlerinin çıkmış en son versiyonu ile kurmak, güncellemeleri takip etmek ve   uygulamak, bir kişisel firewall kullanarak dışarıdan gelebilecek ataklara karşı   kapıları kapatmak ve tüm bu önlemler alındıktan sonra bilgisayarı fiziksel   olarak Internet''e bağlamaktan geçmektedir. Bazı worm''lar zaman zaman o kadar   agresif olmuşlardır ki, daha bilgisayar ilk kurulup güncelleme yapmak için   Internet''e bağlandığı anda bilgisayara sızmayı başarabilmişlerdir. </p>
<p>Worm girmiş bir bilgisayar, kullanıcının haberi olmadan sürekli olarak   bulunduğu ağ üzerinden tüm Internet ağına saldırıda bulunup milyonlarca IP   adresini rastgele deneyerek kendini yaymaya çalışır. Bu nedenle worm''lu bir   bilgisayar genellikle bulunduğu ağda yoğun bir trafik oluşturacağından o   bölgenin Internet erişimini olumsuz yönde etkileyebilir. </p>
<p>Worm''lu bir bilgisayarın bu "hastalığı" antivirüs programları ile taratılarak   tespit edilebileceği gibi, ağ trafiğinde yarattığı yoğun aktiviteden de   anlaşılabilir. Bazı worm''lar için antivirüs üretici firmalar Internet''ten   indirilip çalıştırılabilen küçük ve sadece o worm tipine etkili   tarayıcı/temizleyici programlar yayınlarlar. Ancak bunun bir garantisi yoktur ve   worm bilgisayarı yeniden kurana kadar temizlenemeyebilir. </p>
<p><STRONG>Spyware (Casus Yazılım)</STRONG></p>
Casus yazılımlar (kimi zaman Ad-ware olarak da   isimlendirilir), bilgisayara çeşitli yöntemlerle bulaşabilen programlardır. Bazı   işletim sistemlerinin Internet tarayıcılarının yazılım açıklarından faydalanarak   Web''de gezinirken bile bulaşabildikleri gibi, genellikle kaynağı belirli olmayan   ve başka amaçlara hizmet ediyormuş gibi görünen programların çalıştırılmasıyla   bulaşırlar. Internet''ten indirilen bedava oyunlar, dosya paylaşım programları,   seri numarası üreten programlar, ekran koruyucular, bazı müzik çalarlar ve diğer   bir çok bedava yazılım ne yazık ki asli görevlerinin arkasında aslında birer   casus yazılım olarak çalışmaktadırlar.
<p>Casus yazılımlar virüsler kadar zarar vermeye yönelik olmasa da,   bilgisayarınızda bulunan verileri (şifreler, dosyalar, kredi kartı numaraları,   e-posta adresleri, yazışmalar, dolaşılan web sayfalarının adresleri, vb.) çalıp   uzak merkezlere iletebilirler. Bunlar bilgisayarın ya da bazı programların   kullanımını yavaşlatabilir veya tamamen engelleyebilir. Casus yazılımlar   yardımıyla çalınmış olan şifreler ile banka hesaplarına zarar verilebilir,   hırsızlıklar yapılabilir ya da bilgisayara uzaktan bir korsanın girmesine olanak   sağlanabilir. </p>
<p>Casus yazılımların hizmet ettiği en önemli amaçlardan biri de, kişilerin   Web''de dolaşırken girip çıktığı siteleri tespit etmek ve buna dayanarak ilgi   alanlarını öğrenmeye çalışmaktır. Bu bilgileri merkezlerine Internet aracılığı   ile gizlice ulaştıran casus yazılımlar, daha sonra bu ilgi alanlarına uygun   olarak kişilere Spam reklamlar yollayabilirler. </p>
<p><STRONG>Bilgisayar Korsanlığı (Hacking)</STRONG></p>
Internet ağı üzerinde bir çok bilgisayar   korsanı bulunmaktadır. Bunlar gerçek kişiler olabildikleri gibi, korsanlık   yapmak amacıyla yazılmış ve amaçları Internet''i dolaşıp bilgisayarların   açıklarını araştıran robot yazılımlar da olabilirler. Kullanılan işletim   sistemlerinin (Windows başta olmak üzere) açık ve hatalarından yararlanan   korsanlar bilgisayara kullanıcısının haberi olmaksızın girip kontrol altına   almayı hedeflerler. Bir kere bilgisayara girildikten sonra verilebilecek zarar   ya da çalınabilecek bilgi tamamen korsanın insafına kalmıştır. Hatta çoğu zaman   korsanlar, üniversite gibi büyük kuruluşların ana sunucu bilgisayarlarına   girebilmek için önce daha korumasız olan kişisel bilgisayarlara hücum eder ve   bunları kullanarak ana sistemlere girmeye çalışırlar.
<p>Korsanların kullandıkları yöntemler, özellikle zamanında açıkları yamanmamış   işletim sistemlerine sahip bilgisayarların bu zaaflarından faydalanmak olduğu   kadar, kullanıcıların bilgisizlik ve dikkatsizliklerinden kaynaklanan zaafları   da kullanmayı içerir. Bilgisayarına giriş için hiç şifre koymayan ya da tahmin   edilmesi çok kolay şifreler koyan kullanıcı aslında potansiyel bir bilgisayar   korsanına davetiye çıkarmış demektir. Benzer şekilde, firewall, antivirüs,   antispyware kullanmayan, zamanında güncellemeleri yapmayan kullanıcı da hem   kendini hem de bulunduğu kurumu tehlikeye atmış olmaktadır. </p>
<p><STRONG>Kişisel Firewall</STRONG></p>
Firewall''lar, bilgisayar ağlarını, gelen giden verileri   sürekli inceleyerek dışarıdan gelebilecek saldırılara karşı akıllı biçimlerde   korumaya çalışan yazılım ya da yazılım/donanım sistemlerine verilen addır.   Kişisel firewall yazılımları ise, sadece o bilgisayarı ağ üzerinden gelen   saldırılara karşı korumaya yarayan ve genellikle işletim sistemine entegre   olarak çalışan programlardır.
<p>İşletim sistemleri, karmaşık doğaları gereği Internet üzerinden gelebilecek   saldırılara açık olabilirler. Ayrıca çalıştırılan programlar -istemli veya   istemsizce- sistemde yeni açıklar oluşturabilir ve bir amaca hizmet ederken   (örneğin Internet''ten dosya indirme) bir başka şekilde de zarar verebilirler.   Kişisel firewall programları sistemi, içinde kullanılan programlardan bağımsız   olarak çeşitli saldırılara karşı korumayı hedefler. Kimileri bir program uzak   bir yere ulaşmaya çalışıyorsa şüphelenip kullanıcıya haber verirken, kimileri   bunun yanında kodları değişen (belki virüsün değiştirebileceği endişesi ile)   programları takip edip uyarılar yaparlar. Çoğu firewall korsanların sıklıkla   kullandığı taramaları (bilgisayardaki açıkları bulmak için araştırma) farkedip   bunlara bilgisayarın cevap vermemesini sağlarlar. </p>
<p>Ancak firewall''lar da sonunda birer bilgisayar programı oldukları için bir   kere içeri sızmayı başaran bir zararlının bunları etkisiz hale getirebilmesi de   olasılık dahilindedir. Ya da zaman zaman kullanıcının bilinçsiz davranması   nedeniyle kişi zararlı olabilecek bir Internet trafiğine de sistemin izin   vermesini sağlayabilir. </p>
<p>Windows''un XP öncesi versiyonlarında ve XP''nin Service Pack 2''si öncesinde   işletim sistemine entegre bir firewall ya yoktu ya da çok yetersizdi. XP SP2 ile   beraber daha tatmin edici bir kişisel firewall da sisteme eklendi. Ancak bunun   da açıklarını bulan bazı korsanlar ya da korsan yazılımlar bu yapıyı da aşmayı   başarmaktadırlar. Şu anda ayrıca piyasada satılan bazı profesyonel firewall   yazılımları olduğu gibi, hemen hemen aynı marifetlere sahip ama ticari olmayan   kullanımı parasız yazılımlar da (Sygate Personal Firewall gibi) mevcuttur.   Deneyimler göstermiştir ki, korsan olma potansiyeline sahip şifre kırıcı, ekran   koruyucu, oyun vb. programları indirip kullanma eğilimi göstermeyen, lisanslı ya   da kaynağı güvenlilir yazılımları kullanan, bazı koruma araçlarını bilgisayarına   yüklemiş, güncellemeleri zamanında yapan bir kullanıcı için XP SP2 ve sonrası   işletim sistemleri ile entegre olarak gelen firewall yazılımı yeterli   görünmektedir. </p>
<p><STRONG>Antivirüs ve Antispyware</STRONG></p>
Virüslere ve casus yazılımlara karşı   bilgisayara yüklenen ve bunlar bilgisayara girmeye çalıştıklarında farkedip   engel olan yazılımlardır. Bilgisayara yüklendikten sonra artık bilgisayar her   açıldığında bunlar otomatik olarak geri planda çalışmaya başlarlar ve okunan,   yazılan tüm dosyaları aynı anda kontrol ederler. Bunun da bedeli bilgisayarın   çoğu zaman belirgin bir biçimde yavaş ve uzun açılması ve işlemleri olağandan   daha yavaş yapması olarak ortaya çıkar. Bu tür programlar bilinen onbinlerce   virüsün izini sürmeye çalıştıklarından aslında ortaya çıkan hız düşüşü yapılan   işle karşılaştırıldığında oldukça kabul edilebilir düzeylerde kalır. Her iki tür   tarayıcı da zaman zaman Internet üzerinden üretici firmalarına bağlanıp virüs   tanımlarını güncellerler. Bu, yeni çıkan virüs ve spyware yazılımlarından   haberdar olmak için gereklidir. Her antivirüs ve antispyware yazılımının tüm   virüsleri bulması sözkonusu değildir. Hatta ideal bir yazılım da yoktur. Yeni   çıkan ve hızla yayılan bir virüsün parmak izini bilmeyen yazılım bunu farkedemez   ve virüs bilgisayara bulaşır. Hatta kimi virüsler bir kere bilgisayara bulaşınca   popüler antivirüs yazılımlarını tanıyıp bunları da kullanıcıya farkettirmeden   etkisiz hale getirebilirler. Kullanıcı gönül rahatlığı ile çalışırken aslında   virüs bilgisayara zarar vermeye başlamıştır.
<p>Antivirüs ve antispyware''ler işlevleri nedeniyle genellikle ayrı ayrı bulunan   ve ayrı ayrı yüklenmesi gereken programlardır. Genellikle para ile satılırlar ve   lisanslanmaları gerekir. Piyasada sıklıkla popüler antivirüs programlarının   "kırılmış" halleri de bulunabilir. Ancak bunların içine "kırılma" sırasında   kasıtlı casus programların konmadığı kimse tarafından garanti edilemeyeceği   gibi, yeni çıkan virüslere karşı güncelleme yapmak gerektiği zaman bağltantı   kurdukları üretici firmalar bunların korsan olduğunu anlar ve güncelleme   yaptırmayı reddedebilirler. Son zamanlarda antivirüs, antispyware ve hatta   kişisel firewall''un bir arada paketlendiği programlar da piyasada görülmeye   başlanmıştır. Ancak bunların fiyatları ve sistemde işgal edecekleri bellek ve iş   gücü miktarı da o oranda artmaktadır. </p>
<p>Bazı tanınmış antispyware programları ise tanıtım amacıyla çıkardıkları   parasız versiyonlarında anlık kontrol yapmak yerine kullanıcı istediği zaman   mevcut diski tarama şeklinde çalışırlar. Bunların en popüler olanlarından biri   Ad-Aware''dir. Bunun yanında Internet üzerinden bilgisayarınıza bağlanıp uzaktan   tarama yapan siteler de vardır. Bunların bilgisayarınıza erişimi için kullanıcı   bazı izinler verir ve belki küçük bazı programlar yükler. Bu, kullanıcı için   büyük bir güvenlik açığı yaratmasının yanısıra, son derece yavaş ve kurumsal   Internet trafiğini de olumsuz yönde etkileyebilecek bir yöntemdir; tarafımızdan   önerilmez. </p>
<p>Problemin daha da karmaşık olan yanı, Internet''te sıklıkla bulunabilen bir   çok antivirüs ve antispyware yazılımının bir kısmının da aslında bizzat virüs ve   casus yazılım olmalarıdır. Bunlar normal kullanıcıya sanki onu koruyormuş gibi   görünüp (ki aslında bazı zararlılardan gerçekten de koruyor olabilirler) bir   yandan da casusluk yapan yazılımlardır. Hatta bunlar çok şatafatlı Web siteleri   ile reklamlarını yapıyor da olabilirler. Kişilerin iyi araştırma yapmadan,   bilenlere danışmadan bu tür programları yüklememeleri gerekir. Üniversitemizde,   özellikle Beytepe Kampüsü''nde arkadaş tavsiyesi ile yayılan bu tür bazı   antivirüs yazılımları ile karşılaşılmıştır. Bu yazılımların yüklü olduğu   bilgisayarlar, kullananlar farkında olmadan, zaman zaman Internet trafiğinde   ciddi karmaşalara da sebep olmuşlardır. </p>
<H4>Bilgisayarımı Virüs ve Casus Yazılımlardan Nasıl Korurum?</H4>
Çok geniş   kapsamlı olan bu konuda burada ancak pratik bazı öneriler vermekle   yetinilecektir. Burada genellikle Microsoft Windows işletim sistemlerini   kullanan kullanıcılar hedeflenmiştir. Bunun nedeni bu işletim sisteminin   diğerleri ile karşılaştırıldığında çok daha büyük oranda kullanıcı kitlesine   sahip olması ve işletim sisteminde bulunan açıkların diğerlerinden daha çok   bulunması ve kötüye kullanılmasıdır. Kuşkusuz ki burada anlatılanlar Linux,   MacOS vb. işletim sistemlerini kullanan kullanıcılara da genel fikirler   verecektir.
<p><STRONG>Temel olarak virüs ve casus yazılımlardan korunmanın yolları şöyle   sıralanabilir: </STRONG></p>
<OL>
  <LI><STRONG>Dışarıdan kaynağı belirsiz programları indirmemek, açmamak.</STRONG> Belki   oldukça kısıtlayıcı bir durum olarak görünse de günümüz Internet ortamında ne   yazık ki eskisine göre çok daha "paranoyak" davranmak zorundayız. "Cici" ekran   koruyucular, bedava oyunlar, şifre kırma programları potansiyel birer virüs veya   casus yazılım kaynağı olabilirler. Özellikle kaçak programlar ya da yazılım   anahtarları bulmak için kullanılan "hack/crack" siteleri ideal mekanlardır.   Bunların bir çoğu bir anahtar verebilmek için bile bir şeylerin tıklanmasını,   birşeylere "yes" denmesini isterler. Bu ise aslında kişinin kendi elleriyle   bilgisayarına zararlı yazılımları kurmasından başka birşey değildir. Bunlardan   kesinlikle uzak durulması gerekir. Internet üzerinde bilinen, güvenlirliği   kanıtlanmış, kaçak yazılım yükletmeyen freeware/shareware siteleri çok daha   güvenlidir. </LI>
  <LI><STRONG>Güvensiz e-postaları asla açmamak, içindeki eklentileri (attachment)   çalıştırmamak.</STRONG> Bazen çok güvenilir bir kişiden bile, ya o da farkında   olmadan, ya da onun adıyla, gelen e-postalar potansiyel virüs taşıyıcısı   olabilirler. Özellikle Word dokümanı olan ".doc" uzantılı dosyalar potansiyel   virüs içerebilirler. Bazı e-posta istemcileri de (Outlook gibi),   yazılımlarındaki açık ve hatalardan ötürü kullanıcı istemeden gelen e-postayı   kendi kendilerine açıp çalıştırabilmektedirler. Bunların ayarlarının   yapılmasında, kullanıcının isteği olmadan birşeyleri çalıştıran e-posta   yazılımlarından uzak durulmasında yarar vardır. Bazen virüslü dosyaları e-posta   ile yollayanlar, bunların uzantılarını kullanıcıları kandıracak biçimde   gizleyebilirler. Örneğin, mp3 dosyası gibi zararsız bir dosya uzantısı varmış   gibi gösterilen bir zararlı dosyanın asıl soneki mp3''den sonra 100 adet boşluk   ve ".exe" olabilir ve bazı e-posta istemcileri bu boşlukları gösteremedikleri   için kullanıcılar bu dosyayı mp3 dosyası sanıp tıklayabilirler. Eklentiler   konusunda en iyi davranış, onları açmadan bir yere kaydetmek, uzantısından emin   olmak ve özellikle "doc" dosyası ise, örneğin "Windows Wordpad" vb. başka daha   ilkel bir programla açıp içini iyi-kötü görmeye çalışmak olabilir. </LI>
  <LI><STRONG>Lisanslı işletim sistemleri ve yazılımlar kullanmak.</STRONG> Özellikle   Windows işletim sistemlerinin lisanslı olarak elde edilip kurulmasında büyük   yarar vardır. Lisanssız işletim sistemlerini kullananlar, bunlar için çıkarılan   ve yazılım hatalarına karşı yapılan güncellemelerden çoğu zaman yararlanamazlar.   Ayrıca "crack" olarak elde edilmiş bu yazılımların içine, "cracker" tarafından   istenmeyen kodların yerleştirilmediğinden de emin olmak zordur. Lisanslı işletim   sistemlerinde kullanıcılar "antispyware" gibi ek yazılımları da yükleyip   kullanamazlar. Bu kural işletim sistemlerinin yanında Office gibi diğer sonradan   yüklenen yazılımlar için de geçerlidir. Hacettepe Üniversitesi Bilgi İşlem   Dairesi, kullanıcıların yazılımları lisanslı olarak kullanabilmeleri için   gerekli anlaşmaları ve yazılım teminini yapmıştır. </LI>
  <LI><STRONG>Antivirüs ve Antispyware kullanmak.</STRONG> Ancak bunların yasal olanlarını   temin etmek ve kurmak önemlidir. Kullanıcılarda çok gözlemlenen bir davranış   biçimine de dikkat çekmek gerekir: Kullanıcılar, "nasıl olsa antivirüs   kullanıyorum" deyip, bilgisayar kullanımında daha özensizleşmektedirler. Zararlı   bir program varsa nasıl olsa antivirüs''ün bunu durduracağını düşünen   kullanıcılar, aslında antivirüs''lerin yüzde yüz bir koruma yapamadığını ve hatta   çoğu zaman yeni yayılan virüsleri bulamadığını göz ardı eder ve virüs   kaptıklarının farkına da çoğu zaman çok geç varırlar. Kullanıcıların bu hataya   düşmemeleri gerekir. Piyasada ve Internet dünyasında çeşit çeşit antivirüs ve   antispyware yazılımı mevcuttur. Kural, "en popüleri en iyisidir" değildir. Bir   antivirüs programı ne kadar yaygınsa, onun açıkları, zaafları da o derece iyi   biliniyor anlamına gelir ve bu da virüs yazarlarının işini kolaylaştırır. Diğer   yandan hiç adı sanı duyulmamış bir antivirüs yazılımı şüpheli olabilir,   güncelleme sıklığı yetersiz olabilir ya da teknolojisi daha iyi olan meşhur   programlara göre bilgisayarınızı daha da yavaşlatabilirler. Ne yazık ki serbest   piyasa ortamında birbirlerine karşı avantaj ve dezavantajları bulunan bu   yazılımlardan birini diğerine karşı önermek de oldukça zordur. Bu yazının   yazıldığı tarih itibarıyla lisanslı Windows XP kullanıcıları, Microsoft   firmasının Web sitesinden "Windows Defender (beta)" adlı yazılımı ücretsiz   olarak yükleyip çalıştırabilirler. Bu bir "antispyware" yazılımıdır ve oldukça   etkin olarak çalışabilmektedir. Yine kısa bir süre sonra "Microsoft OneCare"   adında bir antivirüs/antispyware/firewall paketi ABD dışındaki kullanıcılara   sunulacaktır. Ayrıca satılan bu paket için de Hacettepe Üniversitesi Bilgi İşlem   Dairesi gerekli anlaşmaları yapmak için beklemektedir. Şu anda paketin "beta"   versiyonu yüklenip denenebilmektedir. </LI>
  <LI><STRONG>Kişisel firewall kullanmak.</STRONG> Yukarıda firewall başlığı altında da   değinildiği üzere bu konuda da farklı seçenekler vardır. En azından kullanıcının   Windows XP''sine Service Pack 2''yi yüklemesi (bazı işletim sistemleri zaten yüklü   gelmektedir) ve üzerinde hazır bulunan firewall''u etkin hale getirmesi gerekir.   Özel uygulamalar çalıştırmayan bir kullanıcının bu etkinleştirmeyi yaparken   "don''t allow exceptions (istisnalara izin verme)" benzeri seçeneği   işaretlemesinde büyük yarar vardır. Kullanıcıların kullanım sırasında zaman   zaman Windows firewall ayarlarının yapıldığı yere girip, herhangi bir programın   mevcut ayarları değiştirip değiştirmediğine ve yeni açıklara izin verdirip   verdirmediğine bakması yararlı bir davranış olacaktır. Zira bazı casus   programlar bir kez bilgisayara girince mevcut firewall''un bazı ayarlarıyla oynar   ve dışarıdan normalde izin verilmeyen giriş portlarına sistemin izin vermesini   sağlayabilir. </LI>
  <LI><STRONG>Mümkün olduğunca şüpheli Web sitelerini ziyaret etmemek.</STRONG> Windows''da   bulunan bazı açıklardan yararlanan web sitesi yöneticileri, kullanıcının bu   siteleri ziyaret etmesi durumunda casus yazılımları kapabilmesine neden olan   bazı kodlar kullanabilmektedirler. Özellikle "crack" siteleri, oyun siteleri,   şarkı sözü ve mp3 siteleri, "warez" diye isimlendirilen kaçak yazılım siteleri   ve porografik sitelerde bu yöntemler sıklıkla kullanılmaktadır. Bu yazının   yazıldığı tarih itibarıyla riski biraz azaltmak için kullanılabilecek bir   yöntem, Internet Explorer yerine Mozilla Firefox tarayıcısını kullanmak   olabilir. Bu tarayıcı (browser) yazılımı, mevcut IE''ye zarar vermeden, ayrı bir   alternatif olarak bilgisayara yüklenebilir. Bazı özellikleri dolayısıyla IE''nin   yakalandığı tuzaklara yakalanmamaktadır. </LI>
  <LI><STRONG>Sanal makinalar kullanmak.</STRONG> İleri düzey kullanıcıların tercih   edebileceği bir yöntemdir. Piyasada sanal makina (virtual machine) yazılımları   mevcuttur. Bunlardan birini edinip bilgisayarına kuran bir kullanıcı,   bilgisayarının içinde bir pencere olarak sanki başka bir bilgisayar çalıştırır.   Kullanıcı, bunun içine mevcut işletim sistemine bağlı olmadan istediği bir başka   işletim sistemini kurar, "boot eder" ve pencere içinde yeni bir bilgisayar   çalışır. Bu sanal bilgisayarın kendi hard diski zannettiği aygıt aslında esas   hard diskte bulunan zararsız bir dosyadır. Bununla Internet bağlantısı kurulup   her yere güvenle girilip çıkılabilir, istenilen virüslü programlar   çalıştırılabilir. Her şey bu sanal makinanın içinde kalacak ve gerçek bilgisayar   bundan etkilenmeyecektir</LI>
</OL></div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 27);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('cms', 'tr', 'Hacettepe Üniversitesi İçerik Yönetim Sistemi', '<div class="icerik">
<p>Bilgi İşlem  Daire Başkanlığı tarafından hazırlanan ve web sayfalarınızın içeriğini  yönetebileceğiniz İçerik Yönetim Sistemi (HÜ-İYS) hizmete girmiştir.</p>
<p>Bu sistem üniversitemiz birimler/bölümler web sayfalarını yöneten veya yönetecek olan sayfa sorumluları için hazırlanmıştır. Bireysel kullanıcılar sisteme giriş yaptığında yetki hatası alırlar.</p>
<p>Mevcut sayfaların sistemi kullanması için dilekçe ile başvurması gerekmektedir. Dilekçe örneği aşağıdadır.</p>
<TABLE width="100%" border="0" cellpadding="5">
  <TBODY>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon01.png"></TD>
      <TD align="left" valign="middle"><STRONG>HÜ-İYS Nedir?</STRONG><BR>
        HÜ-İYS,  merkezi olarak web sayfalarınızın içeriğini yönetebileceğiniz web tabanlı bir  uygulamadır. Bu uygulama ile web sitenize içerik girişi ve içerik düzenlemesi  yapabilirsiniz. Bu düzenlemeleri yaparken herhangi bir programa ihtiyaç  duymadan tarayıcınız üzerinden işlemlerinizi yapabilirsiniz.</TD>
    </TR>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon02.png"></TD>
      <TD align="left" valign="middle"><p><STRONG>Sisteme Giriş</STRONG><BR>
        Sisteme <A href="http://hu-iys.hacettepe.edu.tr/">http://hu-iys.hacettepe.edu.tr/</A> adresi üzerinden hacettepe.edu.tr eposta hesap bilgileriniz ile  giriş yapabilirsiniz. Sistemi kullanmak için başka bir şifreye ihtiyacınız  yoktur.</p>
          <p><STRONG>Sayfa Sorumluluğu</STRONG><BR>
            Sisteme giriş yaptığınızda sorumlu olduğunuz sayfalara  müdahale edebilirsiniz. Eğer herhangi bir sayfa için sayfa sorumluluğu  tanımlamanız yok ise sistemi kullanamazsınız.</p></TD>
    </TR>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon03.png"></TD>
      <TD align="left" valign="middle"><p><STRONG>HÜ-İYS Bileşenleri</STRONG></p>
          <OL>
            <LI>Menüler</LI>
            <LI>Sayfalar</LI>
            <LI>Haber ve Duyurular</LI>
            <LI>Foto Galeri</LI>
            <LI>Video Galeri</LI>
          </OL></TD>
    </TR>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon04.png"></TD>
      <TD align="left" valign="middle"><STRONG>Şablon Yapısı</STRONG><BR>
        Sistem Bilgi  İşlem Daire Başkanlığı tarafından hazırlanan şablonu kullanmaktadır. Şablon  merkezi olarak değiştirildiğinde sistemi kullanan sayfalar otomatik olarak  değişen şablonu kullanmaya başlayacaktır. <BR>
        <BR>
        <STRONG>Çoklu Dil Desteği</STRONG><BR>
        Sistemde tanımlı  sayfalar için çoklu dil desteği sağlanmaktadır.</TD>
    </TR>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon05.png"></TD>
      <TD align="left" valign="middle"><STRONG>Dosya Yönetimi</STRONG><BR>
        Sayfanızda  kullanacağınız dosyalar(doküman, resim vs.) için her bir sayfa için ayrı olarak  tanımlanmış dosya alanını kullanabilirsiniz.</TD>
    </TR>
    <TR>
      <TD width="128" align="left" valign="middle"><IMG src="/images/hu-iysicon06.png"></TD>
      <TD align="left" valign="middle"><p><STRONG>HÜ-İYS Kimler Kullanabilir?</STRONG><BR>
        HÜ-İYS  aşağıdaki birimler tarafından kullanılabilir.</p>
          <OL>
            <LI>Fakülteler</LI>
            <LI>Bölümler</LI>
            <LI>Birimler</LI>
            <LI>Araştırma Merkezleri</LI>
            <LI>Enstitüler</LI>
            <LI>Yüksek Okullar</LI>
            <LI>Meslek Yüksek Okulları</LI>
            <LI>Öğrenci Toplulukları</LI>
            <LI>Hacettepe Üniversitesi Tarafından  Düzenlenen Kongreler</LI>
          </OL>
        <p><STRONG>HÜ-İYS İçin Nasıl Başvurabilirim?</STRONG><BR>
          HÜ-İYS Kullanmak için <A href="/dosyalar/BGYS-F-23-IYSTalepFormurevizyon.docx"><STRONG>“HÜ-İYS Başvuru Formu”</STRONG></A> ile resmi yazı üzerinden başvurulması gerekmektedir. </p></TD>
    </TR>
  </TBODY>
</TABLE>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 28);
INSERT INTO belge (sayfa_id, ad, adres, tur, sira) SELECT id, '“HÜ-İYS Başvuru Formu”', '/dosyalar/BGYS-F-23-IYSTalepFormurevizyon.docx', 'DOCX', 0 FROM sayfa WHERE slug = 'cms' AND dil = 'tr';
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('hunet-policy', 'tr', 'HUNET Kullanım İlkeleri', '<div class="icerik">
<p><strong>1. Tanımlar</strong></p>
<p><STRONG>Bilişim Kaynağı:</STRONG> Hacettepe Üniversitesi kampüsleri dahilinde bulunan   ve BİD''nin kurup yönettiği bilgisayar ağı (HUNET), bağlı olduğu tüm iç ve dış   ağlar ile bu ağa bağlanan her türlü elektronik cihaz, bilgisayar ve yan   ürünleri. </p>
<p><STRONG>HUNET:</STRONG> Hacettepe Üniversitesi dahilinde bölüm, birim, bina ve kampüs   düzeyinde bilişim kaynaklarını bir ağ yapısı ile birbirine bağlayan ve Internet   erişimini sağlayan ağa verilen genel ad. </p>
<p><STRONG>BİM:</STRONG> Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı bünyesinde   faaliyet gösteren ve ağ, sunucu ve benzeri servislerin tümüne olan erişimi   sağlayan sistemlerin bir araya geldiği ve yönetildiği merkez (Bilgi İşlem   Merkezi). </p>
<p><STRONG>Kampüs Kullanıcısı:</STRONG> Hacettepe Üniversitesi dahilinde bulunan bilişim   kaynaklarını üniversite kampüsleri içinden erişerek kullanan akademik ve idari   personel, öğrenci ya da kullanım hakkı tanınmış özel ya da tüzel kişi. </p>
<p><STRONG>Kampüs Dışı Kullanıcı:</STRONG> Hacettepe Üniversitesi dahilinde bulunan   bilişim kaynaklarını üniversite kampüsleri dışından çeşitli yöntemlerle erişerek   kullanan akademik ve idari personel, öğrenci ya da kullanım hakkı tanınmış özel   ya da tüzel kişi. </p>
<p><STRONG>Ziyaretçi:</STRONG> Hacettepe Üniversitesi dahilinde olmayan, ancak çeşitli   nedenlerle Hacettepe Üniversitesi bilişim kaynaklarına (WEB, FTP vb.) uzaktan   erişenler ile üniversitenin personel ya da öğrencisi olmayıp kampüsler dahilinde   bulunan bazı bilişim kaynaklarına (kablosuz ağ vb.) ulaşan kişi. </p>
<p><strong>2. Yetki Ve Sorumluluk Beyanı</strong></p>
Üniversitemizde Internet ve Intranet   ağının kurulum ve işletmesine ait yetki ve sorumluluk Bilgi İşlem Dairesi   (BİD)''ne aittir. BİD, akademik, idari, eğitim ve araştırma amaçları   doğrultusunda bölüm ve birimlerin bilişim kaynaklarına ulaşabilmerini sağlamak   üzere oluşturulan altyapıyı kurmak, işletmek ve güncellemekle sorumludur. BİD,   bölüm ve birimlerde tespit edilen ana ağ erişim noktalarını kurar, Bilgi İşlem   Merkezi (BİM) ile iletişimi için gerekli kablolama faaliyetlerini yürütür, bu   noktalara kullanıcıların bağlanabilmesi için gerekli ağ anahtarlama cihazlarını   temin eder ve yerleştirir. Sistemi teknik düzeyde planlama ve uygulama   sorumluluk ve yetkisi BİD''ndedir. BİD, binalar içinde kurulan ana erişim   noktaları dışında kalan oda, ofis ve laboratuvar gibi alt birimlerin   bağlantılarından sorumlu değildir; bunlar birimin/bölümün kendi   sorumluluğundadır. Ancak BİD gereken durumlarda ve istek üzerine danışmanlık   hizmeti verebilir.
<p>Hacettepe Üniversitesi bilişim kaynakları kullanıcıları, Hacettepe   Üniversitesi sunucuları üzerinde kendilerine tahsis edilen "kullanıcı   kodu/şifre" ikilisi ve/veya IP (Internet Protocol) adresi kullanılarak   gerçekleştirdikleri her türlü etkinlikten, Hacettepe Üniversitesi bilişim   kaynaklarını kullanarak oluşturdukları ve/veya kendilerine tahsis edilen   Hacettepe Üniversitesi bilişim kaynağı üzerinde bulundurdukları her türlü   kaynağın (belge, doküman, yazılım, vb.) içeriğinden, kaynağın kullanımı hakkında   yetkili makamlar tarafından talep edilen bilgilerin doğru ve eksiksiz   verilmesinden, ilgili kaynağın kullanım kurallarına, üniversite   yönetmeliklerine, Türkiye Cumhuriyeti yasalarına ve bunlara bağlı olan   yönetmeliklere karşı birebir kendileri sorumludur. </p>
<p>Hacettepe Üniversitesi yönetimi, Hacettepe Üniversitesi kullanıcıları ve özel   kullanıcılar ile üçüncü kişi veya kuruluşlar arasında doğabilecek her türlü   ihtilaf durumunda doğrudan taraf olma hakkını saklı tutar. </p>
<p><strong>3. Bilişim Kaynaklarının Kullanımı İçin Genel İlkeler</strong></p>
Bilişim   kaynaklarının, eğitim, öğretim, araştırma-geliştirme, hizmet ve idari   faaliyetler ile ilişkili olan kullanımı esastır. Bu amaçlar dışında kalan tüm   kullanımlar ancak ve ancak yukarıda adı geçen amaçlarla yapılan kullanımı   kısıtlamadığı ve aşağıdaki kural ve ilkelere aykırı olmadığı sürece mümkündür:
<OL>
  <LI>Hacettepe Üniversitesi bilişim kaynakları, bu kaynakları kullananlar   tarafından boşa harcanmamalıdır. </LI>
  <LI>Hacettepe Üniversitesi bilişim kaynaklarını kullanıma sunan birimler, bu   kaynakların kullanımı ile ilgili sorumluluğu da üstlenmiş sayılırlar.   Kaynakların, birim veya bölüme bağlı bir kullanıcı tarafından kurallara uygun   olmayan şekilde kullanılması halinde ilgili birim veya bölüm yönetimi ile BİD   arasında işbirliği olanağı sağlanmalıdır. </LI>
  <LI>Kullanıcılar ağ üzerinden yolladıkları ve/veya aldıkları her türlü veri ile   HUNET''e bağlı bilgisayarlarının içindeki bilgilerinin gizliliğinden,   mahremiyetinden ve güvenliğinden kendileri sorumludur. Kullanıcı,   bilgisayarındaki verilerin önemine bağlı olarak oluşabilecek herhangi bir virüs   - korsan saldırısına ya da teknik kazalara karşı gerekli gördükçe yedekleme   yapmalıdır. </LI>
  <LI>Bölüm veya birimler, kendilerine verilen bilişim kaynaklarını adil olarak ve   üniversitenin diğer kullanıcılarının erişim haklarını engellemeyecek şekilde   kullanmakla sorumludurlar. Yönetim, bu konuda BİD ile işbirliği yapılmalı ve   BİD''nden aldıkları kullanım bilgilerini değerlendirerek, bu kurala aykırı bir   hareket görüyorsa çalışanlarını ya da öğrencilerini uyarmalıdır. </LI>
  <LI>Bölüm veya birimler, kullanıcıların yarattığı giriş ve çıkış trafiğinden   sorumludurlar. Bu konuda BİD''nden gelecek bilgileri ve uyarıları hızla   değerlendirip, aykırı ve istenmeyen trafiği yaratan kullanıcıya gerekli   yaptırımı en kısa zamanda yerine getirmelidirler. </LI>
  <LI>Kullanıcılar, çoğu zaman, bilgisayarlarında bulunan verilerin değerini   önemsemedikleri için gerekli önlemleri almamakta, virüs vb. zararlıların   bilgisayarlarında bulunmasından rahatsız olmamakta veya bunların varlığını   tespit etmek için bir gayret göstermeyebilmektedirler. Ancak bu durumun,   üniversitenin bilişim kaynaklarınının kullanımını da olumsuz derecede etkilediği   çoğu zaman unutulmakta ya da bilinmemektedir. Bölüm veya birim yönetimleri   kullanıcıları bu konuda da bilinçlendirmekle yükümlüdürler. </LI>
  <LI>BİD, güvenliği veya sistemin çalışmasını tehdit edebilecek bir problem   tespit ettiğinde, kişi ya da alt birimin kimliğinin tespiti için ilgili bölüm ya   da birim yönetimi ile hızlı ve sağlıklı bir işbirliği yapabilmeli; bu nedenle   bölüm veya birim yönetimleri, kullanıcıların bağlantıları, IP / MAC adresleri,   ağ erişim cihazı üzerinde hangi soketin hangi bilgisayara ulaştığı gibi   konularda dökümantasyon yapmalı ve bu bilgilerin güncelliğini korumalıdır.   Yönetimler tarafından mümkünse mutlaka yerel ağ yapısından sorumlu bir kişi   görevlendirilmeli ve bu kişiye gerektiği zaman hızla ulaşabilmesi için BİD''ne   gerekli erişim bilgileri verilmelidir. </LI>
  <LI>Birimler veya bölümler, BİD''nin binalarında kurup muhafaza sorumluluğunu   verdiği kablolama sistemi, ağ erişim cihazları ve diğer teçhizat üzerinde, gerek   yazılım gerekse donanım düzeyinde keyfi değişiklikler yapmamalı, bir gereksinim   olduğu takdirde, o birimin daha önceden belirlenip BİD''ne bildirilmiş teknik   sorumlusu tarafından BİD ile irtibata geçilmeli, gerekli değişiklik karşılıklı   bilgilendirme ve onay sonucunda yapılmalıdır. </LI>
  <LI>HUNET ağına bağlanan yerel bilişim kaynakları üzerinden paylaştırılan bilgi   ve dosyalar (bölüm sunucuları, bilgi paylaştırmak için kullanılan kişisel   bilgisayarlar, vs.) kesinlikle genel bilgi paylaşımı kurallarına aykırı   olmamalı, telif hakkı, yasallık, gizlilik, lisans koşulları vd. düzenlemelere   aykırı düşmemelidir. </LI>
  <LI>Hacettepe Üniversitesi bilişim kaynakları üniversite yönetiminin bilgisi ve   izni haricinde hiçbir surette ticari amaçla kullanılmamalı, ticari amaçla   çalışan kuruluşlar arasında haksız rekabete sebep olmamalı, ticari gelir   teminine olanak sağlamak için kullanılmamalıdır. Bu kaynaklar hiçbir surette   devredilemez, kiralanılamaz ve satılamaz. </LI>
  <LI>Hacettepe Üniversitesi''nin iç kullanımına ait hiçbir haber, duyuru, bilgi ve   belge, izin alınmadan HUNET aracılığı ile üçüncü şahıslara iletilmemeli veya   iletilecek ortam oluşturulmamalıdır. </LI>
  <LI>Hacettepe Üniversitesi Bilişim kaynaklarının kullanılması için kullanıcılara   verilmiş olan hiçbir şifre üçüncü şahıslara verilmemeli, üçüncü şahısların   üniversite bilişim kaynaklarına HUNET aracılığı ile erişimine olanak   sağlanmamalıdır. </LI>
  <LI>HUNET ve bağlı bilişim kaynakları hiçbir surette genel ahlaka aykırı   materyali barındırmak ve iletmek; Türkiye Cumhuriyeti yasalarına, bunlara bağlı   yönetmeliklere, Hacettepe Üniversitesi tarafından belirlenmiş kural ve ilkelere   aykırı faaliyetlerde bulunmak; siyasi propaganda yapmak amacıyla kesinlikle   kullanılmamalıdır. </LI>
  <LI>İstenmeyen bilgilerin paylaşımından önce "yasal sorumluluk sınırı   (disclaimer)" koymak yukarıdaki kurallar çiğnendiği zaman bir mazeret olarak   görülemez ve gösterilemez. </LI>
  <LI>Üniversitemiz internet hizmetini Türkiye Bilimsel ve Teknolojik Araştırma Kurumu''nun (TÜBİTAK) bir enstitüsü olan  Ulusal Akademik Ağ ve Bilgi Merkezi (ULAKBİM) tarafından işletilen Ulusal Akademik Ağ''dan (ULAKNET)  sağlamakta olup ULAKNET KULLANIM POLİTİKASI (UKP) ile belirlenen hükümlere tabiidir. <A href="https://ulakbim.tubitak.gov.tr/sites/images/Ulakbim/ukp-v2011.pdf" target="_blank">UKP için lütfen tıklayınız.</A> </LI>
</OL>
<p><strong>4. Uygulama Ve Yaptırımlar</strong></p>
Sunulan bilişim kaynaklarının genel ilkelere   aykırı biçimde kullanılması durumunda Hacettepe Üniversitesi makamları,   kullanımın yoğunluğuna, kaynaklara veya kişi / kurumlara verilen zararın   büyüklüğüne göre kullanıcıyı sözlü ve/veya yazılı olarak uyarma, ağ bağlantısını   süreli veya süresiz olarak kesme, kullanıcı hesabını dondurma, üniversite içi   idari soruşturmanın başlatılması için gerekli girişimlerde bulunma ya da Türkiye   Cumhuriyeti yasaları doğrultusunda adli mekanizmaları harekete geçirme   işlemlerinden bir ya da birkaçına başvurabilir. 
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 29);
INSERT INTO belge (sayfa_id, ad, adres, tur, sira) SELECT id, 'UKP için lütfen tıklayınız.', 'https://ulakbim.tubitak.gov.tr/sites/images/Ulakbim/ukp-v2011.pdf', 'PDF', 0 FROM sayfa WHERE slug = 'hunet-policy' AND dil = 'tr';
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('dorm-access', 'tr', 'HUNET - BEYTEPE Yurt Erişim Protokolü', '<div class="icerik">

