INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('notice-280425', 'tr', 'SÖZLEŞMELİ BİLİŞİM PERSONELİ SINAV DUYURUSU', '<div class="icerik">


<p align="center"><strong>HACETTEPE ÜNİVERSİTESİ</strong></a><br />
    <strong>BİLGİ İŞLEM DAİRE BAŞKANLIĞI</strong><br />
    <strong>SÖZLEŞMELİ BİLİŞİM PERSONELİ DUYURUSU</strong><br />
  Hacettepe Üniversitesi Bilgi İşlem Dairesi Başkanlığı  bünyesinde istihdam edilmek üzere, 31/12/2008 tarih ve 27097 sayılı Resmi  Gazete’ de yayımlanan “Kamu Kurum ve Kuruluşlarının Büyük Ölçekli Bilgi İşlem  Birimlerinde Sözleşmeli Bilişim Personeli İstihdamına İlişkin Esas ve Usuller  Hakkında Yönetmelik” in 8 inci maddesi uyarınca, Hacettepe Üniversitesi Bilgi  İşlem Daire Başkanlığı tarafından gerçekleştirilecek yazılı ve sözlü sınav  başarı sırasına göre 1 (bir) Kıdemli Yazılım Geliştirme Uzmanı(Java), 1 (bir)  Kıdemli Frontend Geliştirme Uzmanı, 1 (bir) Kıdemli Yazılım Geliştirme Uzmanı olmak  üzere toplam 3 (üç) Sözleşmeli Bilişim Personeli alınacaktır.</p>
<p><strong>I- BAŞVURU  ŞARTLARI</strong><br />
    <strong>A- GENEL  ŞARTLAR (NİTELİKLER)</strong><br />
  a) 657  sayılı Devlet Memurları Kanunu’nun 48 inci maddesinde yazılı genel koşulları  taşımak,<br />
  b)  Fakültelerin dört yıllık bilgisayar mühendisliği, yazılım mühendisliği,  elektrik mühendisliği, elektronik mühendisliği, elektrik ve elektronik  mühendisliği ve endüstri mühendisliği bölümlerinden ya da bunlara denkliği  Yükseköğretim Kurulunca kabul edilmiş yurt dışındaki yükseköğretim  kurumlarından mezun olmak,<br />
  c)  Yazılım, yazılım tasarımı ve geliştirilmesi ile bu sürecin yönetimi konusunda  veya büyük ölçekli ağ sistemlerinin kurulumu ve yönetimi konusunda ücret tavanı  iki katını geçemeyecekler için en az 3, diğerleri için en az 5 yıllık mesleki  tecrübeye sahip bulunmak, (Mesleki tecrübenin bilişim personeli olarak  geçtiğinin belgelendirilmesi gerekmektedir. Mesleki tecrübenin belirlenmesinde;  bilişim personeli olarak 657 sayılı Kanuna tabi kadrolu veya aynı Kanunun 4üncü  maddesinin (B) bendi ya da 399 sayılı Kanun Hükmünde Kararnameye tabi  sözleşmeli statüdeki hizmetler ile özel kesimde sosyal güvenlik kurumlarına  prim ödenmek suretiyle işçi statüsünde bilişim personeli olarak geçtiği  belgelenen hizmet süreleri dikkate alınır.)<br />
  d)  Bilgisayar çevre birimlerinin donanımı ve kurulan ağ yönetimi güvenliği  hakkında bilgi sahibi olmaları kaydıyla güncel programlama dillerinden en az  ikisini bildiğini belgelemek,<br />
  e) Belge  olarak öğrenilen programlama dillerinin belirtildiği onaylı lisans veya  lisansüstü transkript belgesi veya mezun olunan bölümden alınan eğitimi yapılan  programlama dillerini belirten onaylı yazı, çalışılan yerden alınan ve  kullanılan programlama dillerini gösteren onaylı yazı veya eğitim kurumlarından  alınan kurs katılım sertifikaları gibi belgeler kabul edilir,<br />
  f) Kamu Kurum ve Kuruluşlarının Büyük Ölçekli Bilgi İşlem  Birimlerinde Sözleşmeli Bilişim Personeli İstihdamına İlişkin Esas ve Usuller  Hakkında Yönetmelik te belirtilen özlük hakları ve diğer kuralları kabul etmek,<br />
  g) Erkek adaylar için muvazzaf askerlik çağına gelmemiş  veya askerlik çağına gelmiş ise muvazzaf askerlik hizmetini yapmış, erteletmiş  veya muaf olmak,<br />
  h) Yoğun iş ortamında, grup içinde çalışma ve paylaşım  düşüncesini benimsemek,<br />
  ı) Yenilikçi yaklaşımlara yönelebilmek ve öğrenmeye açık  olmak,<br />
  i) Analitik düşünme yeteneğine&nbsp;sahip&nbsp;olmak.<br />
  <strong>B. ÖZEL ŞARTLAR</strong><br />
  <strong>KIDEMLİ YAZILIM GELİŞTİRME UZMANI (Java)</strong><strong> &nbsp;</strong><strong> </strong><br />
  <strong>(1 kişi, Tam Zamanlı, Aylık Brüt Sözleşme Ücret Tavanının  3 katına kadar)</strong></p>
<ul>
  <li>Fakültelerin dört yıllık bilgisayar  mühendisliği, yazılım mühendisliği, elektrik mühendisliği, elektronik  mühendisliği, elektrik ve elektronik mühendisliği ve endüstri mühendisliği  bölümlerinden ya da bunlara denkliği Yükseköğretim Kurulunca kabul edilmiş yurt  dışındaki yükseköğretim kurumlarından mezun olmak,</li>
  <li>Spring Boot, Spring Core, Spring Data,  Spring Security, ORM, JPA (Hibernate), Maven, Apache Wicket, JSF, JSP  konularında, tecrübeye sahip olmak. </li>
  <li>En az 5 yıl Spring Framework ve Spring  Boot mimarileriyle kurumsal yazılım geliştirme süreçlerinde çalışmış olmak,</li>
  <li>Kurumsal web tabanlı uygulama  geliştirme konularında tecrübeli olmak,</li>
  <li>Web servisleri (SOAP, REST) konusunda  bilgi ve tecrübe sahibi olmak,</li>
  <li>HTML, CSS, JavaScript ve Angular gibi  web teknolojileri ile çalışmış ve bu konularda deneyim sahibi olmak,</li>
  <li>ORM (Object Relational Mapping)  teknolojileri konusunda deneyimli olmak (tercihen Hibernate veya Spring Data  JPA),</li>
  <li>Versiyon kontrol sistemlerinden (Git,  TFS, SVN vb.) en az biriyle çalışmış olmak,</li>
  <li>MySQL, PostgreSQL, Oracle gibi  ilişkisel veri tabanlarından en az biri ile uygulama geliştirmiş olmak,</li>
  <li>Veri tabanı tasarımı, optimizasyon ve  performans artırımı konusunda tecrübe sahibi olmak,</li>
  <li>Mikroservis mimarisi hakkında bilgi ve  tecrübe sahibi olmak,</li>
  <li>SOLID prensiplerine konusunda bilgi  sahibi olmak. </li>
  <li>Application Container (Docker,  Kubernetis, OpenShipt, …vs) teknolojileri konusunda bilgiye sahip olmak,</li>
  <li>RabbitMQ, Redis teknolojilerini  kullanmış veya bilgi sahibi olmak,</li>
  <li>Büyük sistemlerde (en az 20.000  kullanıcılı uygulamalar) Weblogic, Apache, IIS vb. ortamların kurulumuna ve  yönetimine hakim olmak</li>
  <li>Analitik düşünce ve hızlı problem çözme  yeteneğine sahip olmak,</li>
  <li>Güçlü iletişim becerisine sahip, takım  çalışmasına yatkın olmak.</li>
</ul>
