INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('wireless', 'tr', 'Kablosuz Erişim Servisleri', '<div class="icerik">
<p>Sıhhiye ve Beytepe kampüslerinde YURTLAR BÖLGESİ ve KAMPÜS İÇERİSİNDE açık alanlarda kurulan  wifi sistemi Eduroam ve Hacettepe yayınları ile hizmet vermektedir.</p>
<p>Eduroam bağlantı ayarları ile ilgili güncellemeleri <a href="http://eduroam.hacettepe.edu.tr" target="_blank">http://eduroam.hacettepe.edu.tr</a> web sayfasından takip edebilirsiniz.</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 34);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('personal-pages', 'tr', 'Kişisel Web Sayfaları için Web Servisi', '<div class="icerik">

  <ul>
    <li><a href="/tr/kisisel#2">FTP Bağlantı Ayarları</a></li>
    <li><a href="/tr/kisisel#21">Genel Bilgiler</a></li>
    <li><a href="/tr/kisisel#4">MYSQL Kullanımı</a> </li>
    <li><a href="/tr/database-query">Veritabanı Kontrol Sayfası</a></li>
    <li><a href="/tr/kisisel#5">Kota</a></li>
  </ul>
  <p><strong><a name="2"></a>FTP Bağlantı Ayarları: </strong><br>
  </p>
  <p>FTP programında kullanılacak bağlantı bilgileri aşağıdaki gibidir.<br>
    Host/URL: yunus.hacettepe.edu.tr<br>
    Kullanıcı Adı/Username: kullanıcıadı (hacettepe uzantılı epostanızın @işaretinden önceki kısmıdır)<br>
    Şifre/Password: hacettepe eposta adresinizin şifresi </p>
  <p><strong><a name="21"></a>Genel Bilgiler: </strong></p>
  <p>Web sayfalarınızı oluşturan dosyalar kişisel web sayfanızı taşıyan sunucuda FTP ile açacağınız public_html klasörü içerisinde yer almalıdır.</p>
  <p>Giriş sayfanızın (açılış sayfanızın) ismi index(.html, .htm, .php... gibi) olmalıdır.</p>
  <p>Web sayfanızı herhangi bir tarayıcı yardımı ile         http://yunus.hacettepe.edu.tr/~kullanıcıadı adresinden   görüntüleyebilirsiniz.</p>
  <p><strong>CGI Hakkı </strong><br>
    Tüm kullanıcılarımızın cgi kullanım hakkı bulunmaktadır. public_html                       dizini içindeki tüm dizinlerde CGI kullanım hakkı bulunmaktadır.                       CGI'' larınızın "action" kısmına CGI nızın bulunduğu yeri tanımlamanız                       yeterlidir. CGI'' ınıza web üzerinden erişmeyi deneyince "Not                       Found" biçiminde hata veriyor ise; <br>
    CGI programlarınızı sisteme doğru biçimde yerleştirdikten                       sonra, bu programlara referansları özel bir biçimde vermelisiniz. <br>
    Kişisel web sayfaları için public_html dizinine yerleştireceğiniz                       bir "deneme" CGI programı, http://yunus.hacettepe.edu.tr/~kullanıcıadı/deneme                                             adresinden erişilebilir olacaktır. </p>
  <p><strong><a name="4"></a>MYSQL Kullanımı </strong><br>
    Tüm kullanıcılarımızın mysql kullanım hakkı bulunmaktadır. Mysql kullanmak isteyen kullanıcılarımız veri tabanını istemlerini <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> e-posta yolu ile bildirmeleri gerekmektedir. </p>
  <p><strong><a name="5"></a>Web Kota Uygulaması</strong><br>
    Öğrenci kullanıcıları için 100MB büyüklüğünde disk alanı ayrılmıştır. </p>
  <p>Kişisel web sayfası hazırlama ve yayınlama ile ilgili karşılaşacağınız soru ve sorunlar için <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> adresine e-posta atabilirsiniz. </p>
  <p> </p>
  <p>HACETTEPE ÜNIVERSITESI-BİDB''nin web kullanıcıları   servis politikasında diğer kişi ve kurumlara haber vermeden değişiklik   yapma hakkı saklıdır.   Ayrıca, HACETTEPE ÜNIVERSITESI-BİDB merkezi web sunucusu üzerinde   herhangi bir zamanda teknik değişiklikler yapma hakkına sahiptir. Bu   değişiklikleri önceden kullanıcılara bildirebileceği gibi, anlık olarak   yapılabilecek değişikliklerin önceden duyurula maması da mümkün   olabilir.   Web kullanıcıları bu metinde yer alan bilgileri periyodik olarak izlemek   ve olası değişikliklerden haberdar olmakla yükümlüdürler.</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 35);
