INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('matlab-061118', 'tr', 'Öğrencilerimiz için MATLAB Yazılımı', '<div class="icerik">
<p>Üniversitemizin  Değerli Öğrencileri,<br />
    <br />
  Numerik hesaplamaları, ileri düzey grafikleri ve görüntülemeyi, ve üst düzey  programlama dilini birleştiren, entegre teknik hesaplama ortamı yazılımı olan  MATLAB&nbsp;yazılımını öğrencilerimize temin etmiş bulunmaktayız. &nbsp;<br />
  <br />
  100 eş zamanlı kullanıcı olarak temin edilen MATLAB yazılımı, Hacettepe  Üniversitesi öğrencilerin erişimine açık olup, kampüs anlaşması nedeniyle  sadece kampüs&nbsp;içerisindeki kullanılabilmektedir.&nbsp;<br />
  <br />
  MATLAB R2018b (Windows, Mac, Linux - 64 bit) DVD kurulum kalıpları ve  kılavuzları yazılım depomuzdan temin edilebilmektedir. Ayrıntılı bilgi Yazılım  deposu Mathworks&nbsp;MATLAB (Classroom) sayfasında mevcuttur.<br />
  <br />
  &nbsp; &nbsp; &nbsp; &nbsp; Hacettepe Üniversitesi Bilgi İşlem Portalı (<a href="https://portal.hacettepe.edu.tr/">https://portal.hacettepe.edu.tr/</a>)<br />
  <br />
  &nbsp; &nbsp; &nbsp; &nbsp; Kullanıcı adı: E-posta kullanıcı adınız  (@hacettepe.edu.tr eklemeyiniz)<br />
  &nbsp; &nbsp; &nbsp; &nbsp; Şifre: Mevcut eposta şifreniz<br />
  <br />
  Portal Sol menüden &quot;BIDB UYGULAMALARI &gt; Yazılım Deposu&quot;, iç sol  menüden &quot;Akademik Yazılımlar &gt; Mathworks MATLAB (Classroom)&quot;<br />
  <br />
  Bilginize sunulur. Saygılarımızla.&nbsp;<br />
  <br />
  Bilgi İşlem Daire Başkanlığı</p>

   
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 38);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('alumni-email', 'tr', 'Hacettepe Üniversitesi Mezun Hesabı', '<div class="icerik">
<p>
  Hacettepe Üniversitesi Elektronik Posta Sistemlerinde kullanıcılarımızın daha verimli ve etkili bir şekilde iletişim kurmasına yardımcı olmak amacıyla iyileştirme ve geliştirme çalışmaları yapılmış, 11 Mayıs 2022 tarihinden itibaren <strong>yeni e-posta sistemi (Microsoft Exchange)</strong> kullanılmaya başlanmıştır.</p><p>
  Mezun öğrencilerimizin Üniversitemize bağlılıkları göz önünde bulundurularak, yürürlüğe giren <strong><em>8.12.2022 tarih ve 2022-000 sayılı Senato kararına</em></strong> istinaden Hacettepe Üniversitesi mezunlarının Mezunlar Derneği üyesi olmadan kurumsal e-posta almalarına olanak sağlanmıştır. </p><p>
  <strong>Mezun Hesabını Kimler Alabilir?</strong><br>
  Üniversitemizin ön lisans, lisans, yüksek lisans ve doktora programlarını tamamlayarak mezun olmuş tüm Üniversite mensuplarımız bu hizmetten faydalanabilmektedir.</p><p>
  <strong>Mezun Hesabımı Nasıl Alabilirim?</strong><br>
  E-posta Yönergesine göre <strong>@hacettepe.edu.tr</strong> uzantılı mevcut kurumsal elektronik posta hesapları mezuniyet tarihinden 90 gün sonra kullanıma kapatılmaktadır. Kullanıcı hesabının kapatılmasından sonra mezunun kendisi tarafından, </p><p>
  1- <strong>https://portal.hacettepe.edu.tr</strong> adresinden <strong>&ldquo;Yeni Hesap Açma&rdquo;</strong> butonunu kullanarak veya<br>
  2-Mezun olduğunu gösteren bir belge ile Bilgi İşlem Daire Başkanlığına şahsen başvurularak e-posta hesabı açılabilmektedir.<br>
  <strong>Mezun Hesabının Alt Alan Adı Nedir?</strong><br>
  Açılacak mezun hesaplarında &ldquo;@&rdquo; işaretinden sonra, &ldquo;mezun.hacettepe.edu.tr&rdquo; alt alan adı kullanılacaktır.<br>
  <strong>Mezun Hesabı ile Hangi Hizmetlerden Faydalanabilirim?</strong></p>
<ul>
  <li>Tanımlanacak mezun hesapları sadece iletişim için kullanabilecektir. </li>
  <li>Microsoft&rsquo;un Office 365 Mail Hizmeti kullanılacaktır.</li>
  <li>Sunulan mail hizmetinde her kullanıcıya epostalarını saklayabilecekleri 50gb alan verilmiştir.</li>
</ul>
<p><em>Üniversitemizin yaptığı protokoller ve anlaşmalar gereği mezun hesabı alacak kullanıcılarımız proxy (e-kaynak) hizmetinden, yazılım deposundaki yazılımlardan, Office programları gibi hizmetlerimizden <strong>faydalanamayacaklardır.</strong></em></p><p>
  <strong>Mezun Hesabıma Nasıl Giriş Yapabilirim?</strong><br>
  Bilgi İşlem Daire Başkanlığı Portalından mezun hesabı açıldıktan sonra <a href="https://outlook.office.com/" target="_blank">https://outlook.office.com/</a> ara yüzünden oturum açarak hesabınıza erişim sağlamanız gerekmektedir.</p><p>
  <strong>Mezun Hesabımın Kullanıcı Adını Unuttum Nasıl Öğrenebilirim?</strong><br>
  Bilgi İşlem Daire Başkanlığı Portalından &ldquo;Kullanıcı Adımı Unuttum&rdquo; butonunu kullanarak kullanıcı adınızı hatırlamanız gerekmektedir.</p><p>
  <strong>Mezun Hesabımın Şifresini Unuttum Nasıl Öğrenebilrim?</strong><br>
  Bilgi İşlem Daire Başkanlığı Portalından &ldquo;Şifremi Unuttum&rdquo; butonunu kullanarak yeniden şifre oluşturmanız gerekmektedir.</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 39);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('mission-vision', 'tr', 'Misyon ve Vizyon', '<div class="icerik">

    <p>Misyonumuz teknolojiyi yakından izleyerek üniversitemizin bilgi işlem  sistemini işletmek; eğitim, öğretim ve araştırmalara destek sağlamak,  üniversitemizin ihtiyaç duyacağı diğer bilgi işlem hizmetlerini eksiksiz olarak  yerine getirmektir. </p>
    <p> Vizyonumuz, Türkiye''deki üniversiteler arasında bilişim altyapısı, kullanıcı  memnuniyeti, düzenlenen etkinlikler, verilen servis kalitesi ve çeşitliliği  bakımından en üst sıraya yerleşmek; dünyanın saygın üniversitelerinin  bilgi-işlem merkezleri ile kıyaslanabilir kalite ve teknolojiye sahip  olabilmektir. </p>

</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 40);
