INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('proxy-spam', 'tr', 'Proxy-Spam Kontrol', '<div class="icerik">

<p><b>Proxy hesabınız engellenirse ne  yapmalısınız?</b><br />
1. Elektronik posta hesabınızı  kullandığınız tüm cihazları (telefon, tablet, bilgisayar) mutlaka virüs  taramasından geçirmeniz gerekmektedir.<br />
2. Virüs tarama işleminin  yapıldığını anlatan bilgilendirme mailini bidb@hacettepe.edu.tr adresine  göndermeniz gerekmektedir.<br />
3. Göndermiş olduğunuz mail dikkate  alınarak Proxy engeliniz kaldırılır. Proxy engeliniz kaldırıldıktan sonra  mutlaka şifrenizi portal ekranımızda yer alan “Şifre Değiştir” butonunu  kullanarak değiştirmeniz gerekmektedir.</p>
<p><b>Şifre Değişikliğinde  Dikkat Edilecek Hususlar</b></br>

 
  1-Seçeceğiniz parola en az 8, en fazla 15 karakter olmalıdır.<br />
2-Seçeceğiniz parola içerisinde bir büyük harf, bir küçük harf, bir  rakam ve bir özel karakter (<br />
~!@#?$%^&amp;()_- ) mutlaka olmalıdır.<br />
3-Seçeceğiniz parola, teknik sınırlamalar nedeniyle  (ı,İ,ğ,Ğ,ş,Ş,ü,Ü,ö,Ö,ç,Ç) harflerini içermemelidir.</p>




<p><b>E-posta hesabınız engellenirse ne  yapmalısınız?</b><br />
  1. Elektronik posta hesabınızı  kullandığınız tüm cihazları (telefon, tablet, bilgisayar) mutlaka virüs  taramasından geçirmeniz gerekmektedir.<br />
  2. Virüs tarama işleminin  yapıldığını anlatan bilgilendirme mailini bidb@hacettepe.edu.tr adresine  göndermeniz gerekmektedir.<br />
  3. Göndermiş olduğunuz mail dikkate  alınarak E-posta engeliniz kaldırılır. E-posta engeliniz kaldırıldıktan sonra  mutlaka şifrenizi portal ekranımızda yer alan “Şifre Değiştir” butonunu  kullanarak değiştirmeniz gerekmektedir.<br />
  <b>Şifre Değişikliğinde Dikkat Edilecek  Hususla</b>r</p>
<ul>
<ul>
  <li>Seçeceğiniz şifre, 8  karakterden oluşmalıdır.</li>
  <li>Seçeceğiniz şifre  mutlaka bir büyük harf, bir küçük harf, bir rakam ve özel karakter içermelidir.</li>
  <li>Seçeceğiniz şifre,  teknik sınırlamalar nedeniyle &quot;ı,I,g,G,s,S,ü,Ü,ö,Ö,ç,Ç&quot; harflerini ve  bazı noktalama işaretlerini içermemelidir.</li>
</ul>


</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 49);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('sas-191018', 'tr', 'SAS (Statistical Analysis Software) Yazılım Duyurusu', '<div class="icerik">
<p>Üniversitemizin  Değerli Akademik ve İdari Personeli&nbsp;<br />
    <br />
  &nbsp; &nbsp; &nbsp; SAS 9.4 için 29 Haziran 2019 tarihine kadar geçerli olan  lisanslar temin edilmiştir. Kullanıcılarımız kalıcı lisanslarla SAS yazılımını  kullanmaya devam edebilecektir.&nbsp;Ayrıntılı bilgi Yazılım Deposu SAS  (Statistical Analysis Software) sayfasında mevcut olup Hacettepe Üniversitesi  Bilgi İşlem Daire Başkanlığı Portalından erişmek&nbsp;mümkündür (<a href="https://portal.hacettepe.edu.tr/">https://portal.hacettepe.edu.tr/</a>).  Öğrencilerimizin kullanımı ve yazılım lisansının güvenliği açısından bölüm  sorumluları üzerinden ortak öğrenci&nbsp;laboratuvarlarında yazılımın kurulması  ve hizmete sunulması önerilmektedir.<br />
  <br />
  Bilginize sunulur. Saygılarımızla.&nbsp;<br />
  Bilgi İşlem Daire Başkanlığı</p>

   
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 50);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('services', 'tr', 'Birimler Web Sayfaları için Web Servisi', '<div class="icerik">
  
  <ol>
    <li><a href="/tr/servis#5">Başvuru Şekli</a></li>
    <li><a href="/tr/servis#6">Kullanıcı Kodu Sorumlularının Sahip Olması Gereken Özellikler</a></li>
    <li><a href="/tr/servis#7">Kullanıcı Kodunun Açılması</a></li>
    <li><a href="/tr/servis#8">Yeni Şifre Talebi</a></li>
    <li><a href="/tr/servis#9">Alias (Sanal) E-posta Hizmeti</a></li>
    <li><a href="/tr/servis#11">Teknik Özellikler</a></li>
    
    <li><a href="/dosyalar/BGYS-F-12WebKullaniciKoduTalepFormurevizyon.docx">Başvuru Dilekçesi Örneği</a> (FTP ile yönetilecek web sayfaları için)</li>
    <li><a href="/tr/cms">Web sayfaları içeriği yönetmek için Web İçerik Yönetim Sistemi (HÜ-İYS) </a></li>
    <li><a href="/tr/servis#12">Soru ve Sorunlarınız İçin İletişim</a></li>
  </ol>
  <p><strong><a name="5"></a>1. Başvuru Şekli</strong><br>
  </p>
  <p>Öğrenci toplulukları kullanıcı kodu edinebilmek için öncelikle HÜ   Sağlık, Kültür ve Spor Daire Başkanlığı''na başvurmalıdır. Sağlık,   Kültür ve Spor Daire Başkanlığı''nın ilgili yazısı esas alınarak   kullanıcı kodu açılmaktadır.</p>
  <p>Etkinlik ve organizasyonlar, kullanıcı kodu açtırmak için   organizasyonu düzenleyen birim yöneticisi tarafından onaylanmış bir   dilekçe ile BİDB''ye başvurmalıdır. </p>
  <p>Başvuru dilekçesinde kullanıcı kodu talebinin gerekçeleri, kullanıcı   kodundan sorumlu olacak kişi/kişilerin adı ve soyadı, ünvanı, telefon   numarası ve  Hacettepe uzantılı e-posta adresi belirtilmelidir.</p>
  <p><strong><a name="6"></a>2. Kullanıcı Kodu Sorumlularının Sahip Olması Gereken Özellikler</strong><br>
    Kullanıcı koduna sahip olan kişi/kişiler, alias (sanal) adresin                       yönlendirildiği kişilerdir. Bu kişi/kişilerin HTML bilgisine veya                       web sayfası hazırlamaya yönelik araçları kullanabilme becerisine                       sahip olmaları gerekmektedir.</p>
  <p><strong><a name="7"></a>3. Kullanıcı Kodunun Açılması</strong><br>
    Kullanıcı kodu isteği HÜ BİDB''ye ulaştıktan ve ilgili makamlarca   onaylandıktan sonra kullanıcı kodunun açılması için gerekli   işlemler yapılır. Kullanıcı kodu ve web sayfası ile ilgili tüm bilgiler,   kod açıldıktan sonra sorumlu kişi/kişilerin Hacettepe uzantılı e-posta adresine gönderilir.</p>
  <p><strong><a name="8"></a>4. Yeni Şifre Talebi</strong><br>
    Kullanıcı koduna ait şifrenin unutulması veya kaybolması durumunda varolan kullanıcı kodu için yeni bir şifre oluşturulur   ve sayfa sorumlusunun e-posta adresine gönderilir. Yeni şifre talebi için web sayfasından sorumlu olan kişi/kişilerin <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> adresine başvurmaları gerekmektedir. Öğrenci topluluklarının yeni şifre   talepleri, topluluğun akademik danışmanının ilgisi ile gerçekleşir.</p>
  <p><strong><a name="9"></a>5. Alias (Sanal) E-posta Hizmeti</strong><br>
    Kullanıcı kodu açıldığında e-posta adresi olarak  kullanıcıkodumaster@hacettepe.edu.tr    şeklinde bir adres verilir.  Bu alias (sanal) bir adrestir. Bu adresin kullanıcı    adı ve şifresi yoktur. Sadece yönlendirmelidir. Bu adres kullanıcı kodu sorumlularına    yönlendirilmiştir. Bu kişilerin e-posta adresleri "hacettepe" uzantılı olmak    zorundadır.<br>
    Örneğin: webmaster@hacettepe.edu.tr alias bir adrestir ve Web Birimi''  nde çalışan  personele yönlendirilmiştir. Bu adrese e-posta atıldığında, e-posta  bu birimde çalışan tüm personele gelir. Bu postaya cevap vermek icin personel  kendi kişisel e-posta hesabını kullanır. </p>
  <p><strong><a name="11"></a>6. Teknik Özellikler</strong><br>
  </p>
  <p>Güvenlik nedeniyle web sunucusuna Hacettepe Üniversitesi yerleşkeleri dışından ftp yapılamamaktadır. </p>
  <p>Web sunucusunun karakter seti ISO-8859-9 dur. UTF-8 karakter seti kullanılmamaktadır. </p>
  <p> Web sayfalarında PHP, MySQL desteği verilmektedir.</p>
 
  <p><strong><a name="12"></a>7. Soru ve Sorunlarınız İçin İletişim</strong><br>
    Kullanıcı kodu ile ilgili soru/sorunlar, detaylı açıklama                       (varsa hata mesajları ile birlikte) <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> adresine iletilmelidir. </p>
  <hr>
  HACETTEPE ÜNIVERSITESI-BİDB''nin web kullanıcıları servis politikasında   diğer kişi ve kurumlara haber vermeden değişiklik yapma hakkı   saklıdır. Ayrıca, HACETTEPE ÜNIVERSITESI-BİDB merkezi web sunucusu   üzerinde herhangi bir zamanda teknik değişiklikler yapma hakkına   sahiptir. Bu değişiklikleri önceden kullanıcılara bildirebileceği gibi,   anlık olarak yapılabilecek değişikliklerin önceden duyurulamamasıda   mümkün olabilir.
  <p>Web kullanıcıları bu metinde yer alan bilgileri   periyodik olarak izlemek ve olası değişikliklerden haberdar olmakla   yükümlüdürler.</p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 51);
INSERT INTO belge (sayfa_id, ad, adres, tur, sira) SELECT id, 'Başvuru Dilekçesi Örneği', '/dosyalar/BGYS-F-12WebKullaniciKoduTalepFormurevizyon.docx', 'DOCX', 0 FROM sayfa WHERE slug = 'services' AND dil = 'tr';
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('disclaimer', 'tr', 'Sorumluluk Sınırı', '<div class="icerik">
<p align="justify">Bu site üçüncü sahıslar tarafından kontrol edilen İnternet sitelerine bağlantılar sağlamaktadır. Bu üçüncü şahıs sitelerindeki bilgiler, ürünler ve hizmetler ile kurumumuzun hiçbir şekilde herhangi bir menfaat bağlantısı söz konusu değildir. Yine ilgili üçüncü şahısların web sitelerinde yayınlayabileceği herhangi bir bilgi ve içerikle de bölümümüzün bir ilgisi ve kontrolü olamaz. Bu site ve üçüncü şahıs sitelerindeki bilgiler *olduğu gibi* sağlanmaktadır ve açık ya da dolaylı hiç bir garanti verilmemektedir.</p>
<p align="justify">Sitemizde verilen dahili bilgiler bir otomasyon sistemi üzerinden sağlanmakta ve içeriği sıklıkla güncellenmektedir. Yine de kurumumuz, bu sitedeki ya da üçüncü şahıs sitelerindeki malzemelerin kullanımı ya da kullanım sonuçları konusunda, doğruluk, kesinlik, zamanında olmaklık, güvenilirlik ya da başka açılardan hiç bir garanti vermez; her türlü teknik ve insani hataya karşı, burada verilen herhangi bir bilgi ile ilgili olarak site ziyaretçisinin görebileceği maddi ve manevi herhangi bir zarardan kurumumuz nezdinde özel veya tüzel bir kişinin sorumluğu bulunamaz. Ziyaretçi, verilen bilgilerin doğruluğunu sorgulamak ihtiyacı duyduğu takdirde başka kaynaklardan yararlanmak zorundadır.</p>
<p align="justify">Sitemizin ziyaretçisi, bu siteyi kullanmakla yukarıda belirtilen uyarıları anlamış ve doğabilecek tüm maddi ve manevi zararın tazminini de üstlenmiş kabul edilir.</p>

</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 52);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('spam', 'tr', 'SPAM ve PHISHING Hakkında', '<div class="icerik">
<p><strong>Spam</strong></p>
<p>Hemen hemen her e-posta kullanıcısı her gün posta kutusunda   istemediği bir çok reklam vs. amaçlı e-posta ile karşılaşmaktadır. Internet   dünyasında alıcının istemi dışında gönderilen bu tür mesajların tümüne SPAM adı   verilmektedir. Spam, aslında 1960''lı yılların sonunda İngiltere''de satılan bir   konserve markasıydı. 1970 yılında İngiltere televizyonunun ünlü komedi programı   Monty Phyton''da, işlenmiş gıda yemek istemeyen bir çiftin bir lokantanın   menüsünde Spam içeren ürünlerden başka birşey bulamayıp bu ürünü yemek zorunda   kalmaları konu edilmişti. O tarihte çok popüler olan bu skeçten ilham alınarak   istenmeyen reklam amaçlı e-postalara da Spam adı verilmeye başlanmıştır.</p>
<p>Spam mesajlar günümüzde dünya günlük Internet posta trafiğinin %70''inden   fazlasını oluşturmaktadır. Spam göndericileri genellikle Viagra türevi ilaçlar,   ünlü saat markalarının kopyaları, zor durumdaki bir Afrika ülkesinin sürgündeki   kralının para transfer istekleri vb. konularda alıcıları ikna etmeye çalışan   e-postalar yollarlar. Bu e-postaların genellikle uzak doğu, doğu Avrupa ve kuzey   Amerika''dan geldiği tespit edilmektedir. Spam ile ilgili istatistiklere göre   spam mesaj alanların yaklaşık binde biri bu mesajlara inanmakta ve söyleneni   yapmaktadırlar. Bu da, bir anda milyonlarca kişiye spam gönderildiğine göre çok   büyük bir müşteri kitlesi anlamına gelmektedir. Çeşitli yasal takipler sonucu   yakalanan bazı spam göndericilerinin bu yolla milyonlarca dolara sahip olduğu   gözlenmiştir. </p>
<p>Spam mesajları sadece sahtekarlık amaçlı mesajlar olarak göstermek doğru   olmayabilir. Yerli veya yabancı birçok kişi ya da firma, ürün ve hizmetlerini en   kısa ve ucuz yoldan insanlara tanıtabilmek amacıyla toplu e-postalar   göndermektedirler. Ancak gerek bu şekilde gelen mesajların güvenilirliğinin   olmaması, gerekse öyle ya da böyle alıcının istemi dışında geliyor olmaları   bunların da aynı kategoride değerlendirilmelerine neden olmaktadır. </p>
<p>E-posta mesajlarında teknik olarak yollayanın adını ve adresini gerçek dışı   olarak her şekilde göstermek mümkündür. Örneğin ilk bakışta gönderen kişi olarak   sizin ad ve adresinizin görüldüğü bir mesaj, herhangi bir başka kişiye sizin   veya bağlı bulunduğunuz kurumun hiç ilgisi olmadan gönderilebilir. Mesajın   başlık kısmının detayları özel olarak incelenip gönderildiği IP adresi   bulunabilse dahi, uzman korsanlar bulundukları yerden başka yerlere ve oralardan   da yine başka yerlere bağlanıp oradan yalan adresli mesajlar atabilirler ve   bunların tespiti pratikte imkansız denecek kadar zor olabilir. Bu nedenle spam''ı   yollayan da isterse gerçek kimliğini ve yerini kolayca gizleyebilir. </p>
<p>Spam yollayıcılarının beslenme kaynağı, spam yollanacak e-posta adresleridir.   Bir spam''cı ne kadar çok e-posta adresine sahipse o kadar çok müşteri   potansiyeli var demektir. Bu nedenle e-posta adresleri ayrıca alınıp satılan   ticari bir değer haline de dönüşmüştür. Hatta, el altından yüzbinlerce e-posta   adresinin depolandığı CD''ler bile satılmakta; üstelik bunların reklamları da   yine Spam mesajlarla yapılmaktadır. </p>
<p>E-posta adreslerini ele geçirmenin çeşitli yolları vardır. Ancak çoğu zaman   bu adresler, adres sahiplerinin kendileri tarafından bilinçsizce spam''cı   kişilere ulaştırılmaktadır: </p>
<OL>
  <LI><STRONG>"Bedava Üyelik" gerektiren siteler:</STRONG> Şarkı sözü sitelerinden forumlara   kadar birçok site, kullanımının ücretsiz olduğunu, ancak sadece e-posta adresi   ile üyelik gerektiğini söylerler. Eğer site, özel olarak aldığı e-posta adresini   kimseye vermeyeceğini ve spam amaçlı olarak kullanmayacağını açıkça ifade   etmiyorsa büyük bir ihtimalle bu adres bir veritabanında spam''cılara satılmak   üzere depolanacaktır. Hatta kimi siteler bunu açıkça yazsalar dahi   kullanıcılardan topladıkları adresleri spam amaçlı olarak kullanmaktadırlar. <BR>
      <BR>
  </LI>
  <LI><STRONG>E-Posta yönlendirmeleri (forwarding):</STRONG> Bazen e-posta ile bir   tanıdıktan gelen mesaj, fıkra, resim, vs. çok hoşa gider ve kullanıcı da hemen   bunu kendi tanıdıklarına yönlendirir. Yönlendirirken e-postanın içinde daha önce   gönderenlerin de adresleri birikir. Sonunda dağ gibi biriken bu mesajlar bir   spam''cının eline geçer. Bu, alıcıların herhangi birinin bilgisayarında bulunan   bir casus yazılım ile olabileceği gibi, alıcının kendisi spam''cılara para   karşılığında adres satan bir kişi bile olabilir. Bazı mesajlar özellikle   kullanıcıların duygularını sömürecek şekilde hazırlanır. Örneğin çok popüler bir   ürünün aslında kanserojen olması; milli ve manevi değerlere hakaret içeren web   sitelerini protesto etmek için oy kullanılması; aslında hiç olmayan kanserli bir   kıza yardım istekleri; şans getireceğine inandırılan mesajlar ve bir çoğu buna   örnek olabilir. <BR>
      <BR>
  </LI>
  <LI><STRONG>Web siteleri:</STRONG> Dünyadaki Web sitelerini dolaşıp veri toplayan robot   yazılımlar mevcuttur. Bunlar, siteleri tararlar ve içlerinde geçen e-posta   adreslerini bulmaya çalışırlar. En çok yakalamaya çalıştıkları karakter "@"   işaretidir. Bu nedenle bazı sitelerde e-posta adresleri, "filanca (at)   falanca.com" şeklinde yazılırlar ki bu tür robotlara daha az takılsın. <BR>
      <BR>
  </LI>
  <LI><STRONG>Bilgisayar virüsleri:</STRONG> Kişinin bilgisayarına giren ve bu amaçla   tasarlanmış bir virüs, kişinin haberi olmadan e-posta programının (Outlook vb.)   adres defterindeki ve hatta birikmiş tüm e-postalardaki adresleri toplayıp yine   Internet üzerinden spam''cılara ulaştırabilmektedir. </LI>
</OL>
<p>Spam''dan korunmak için tam bir formül olmasa da, en azından bazı önlemler   almak, bunların sayısını azaltmakta etkili olabilir: </p>
<p>  </p>
<OL>
  <LI><STRONG>Ücretsiz e-posta adresi veren bir yerden (GMail, Yahoo, Hotmail, vb.)   ayrı bir adres almak ve üye olunmasını isteyen sitelere e-posta adresi olarak   bunu vermek.</STRONG> Zaman zaman da bu adresle girip biriken tüm postaları (ki bu   sizin normal adresiniz olmadığına göre faydalı bir e-posta gelmesi   beklenmemektedir) tek bir hamle ile temizlemek. <BR>
      <BR>
  </LI>
  <LI>Bazı yazılı formlarda da e-posta adresi sorulmaktadır. Eğer çok güvenilen   bir yer değilse bunlara da yukarıdaki işlem uygulanabilir. <BR>
      <BR>
  </LI>
  <LI><STRONG>Gelen ve başka insanlara forward''lamak istediğiniz mesajların içeriği ile   oynayıp varsa içerdiği başka e-posta adres başlıklarını silmek ve göndereceğiniz   kişilerin e-posta adreslerini "To (Kime)" satırı yerine "BCC" satırına   yazmak.</STRONG> BCC (Blind Carbon Copy) ile e-posta yollanmış bir kişinin adresi   diğer alıcılar tarafından görülmeyecektir. Bu da adreslerin yayılmasını   engelleyecektir. <BR>
      <BR>
  </LI>
  <LI><STRONG>Spam''cıya varlığınızı sezdirmemek.</STRONG> Gelen herhangi bir istenmeyen   mesajda "bu mesajı almak istemiyorsanız şurayı tıklayın ya da şuraya mesaj atın"   benzeri bir ibare bulunabilir. Bunlara uyup cevap vermek, spam''ı alanı o   listeden çıkarmayacağı gibi, spam''cıya da o adresin gerçekten geçerli ve okunan   bir adres olduğu bilgisini verir ve bu daha sizin spam''cının adres defterindeki   yerinizi perçinler. <BR>
      <BR>
  </LI>
  <LI><STRONG>Gelen mesajları bir başkasına ya da bir tartışma listesine   "forward"lamadan önce içeriğinin doğruluğunu kontrol etmek.</STRONG> Örneğin   Atatürk''e karşı düşmanlık içerdiği iddia edilen ve "aman sakın siteye girip   sayacını arttırmayın, şuraya tıklayıp protesto edin ve çevrenizdekilere   yollayın" gibi bir söylem içindeki mesajda bahsedilen site gerçekte hiç   olmayabilir ya da yıllar önce açılıp kapanmıştır. Bu tür mesajlara "hoax",   "scam", "con" vs. isimler verilir. Bunların doğruluğunu kontrol etmek için   popüler arama motorları kullanılabilir. Örneğin Google''da "hoax checking"   kelimeleri girilirse e-posta ile dolaşan "şehir efsanelerine" ait sitelere   ulaşmak mümkündür. <BR>
      <BR>
  </LI>
  <LI><STRONG>Kişisel Web sitelerine mümkün olduğunca e-posta adreslerini formal   olmayan yöntemlerle ("falanca (-at-) filanca (nokta) com" gibi) yazmak.</STRONG> Bu   yöntemle otomatik tarama robotları sitenize girdiği zaman bunun bir e-posta   adresi olduğunu anlamayacaktır. <BR>
      <BR>
  </LI>
  <LI><STRONG>Antispyware ve antivirüs programları kullanmak.</STRONG> <BR>
      <BR>
  </LI>
  <LI><STRONG>Yasal olmayan veya kaynağı belirsiz yazılımları yüklememek,   çalıştırmamak.</STRONG> Şifre kırıcı, şifresi kırılmış, yasal olmayan programların ve   oyunların çoğu birer Trojan (Truva Atı)''dır. Yani bunların perde arkasındaki   işlevi bir şekilde zarar vermektir. Bunlar aynı zamanda spam''cılara sizin ve   adres defterinizdeki kişilerin adreslerini yollamak için çalışabilirler. Siz bu   programları kendi rızanızla yükleyip çalıştırdığınız için virüs sayılmazlar ve   antivirüs programları da sizi uyarmaz. </LI>
</OL>
<p>Hacettepe Üniversitesi Bilgi İşlem Dairesi, @hacettepe.edu.tr uzantılı   e-posta adresleri üzerinde Spam kontrolu yapmakta ve şüpheli mesajlar "Junk   Mail" klasörüne atılmaktadır. Bu klasör de belirli aralıklarla -kota problemleri   nedeniyle- otomatik olarak silinmektedir. </p>
<p>Bir mesajın Spam olup olmadığını anlamak insan için kolay olsa da bilgisayar   için durum aynı değildir. Otomatik tarayıcılar bazı popüler anahtar kelimeleri   (örneğin Viagra gibi) mesaj içinde ararlar, mesajın "from" satırındaki ismin   anormal sayıda kişiye mesaj atıp atmadığını tespit etmeye çalışırlar, hatta   dünya üzerinde belirli noktalara kurulu spam veritabanlarına bağlantı kurarak   yeni anahtar kelimeleri edinip kontrollerini bunları kullanarak yapmaya   çalışırlar. Spam yollayıcıları da diğer yandan bu tarayıcılara yakalanmamak için   anahtar kelimeleri bozarak yazarlar (örneğin "\/ | A AA GG rA" gibi) ya da   yazıları normal metin yerine bir resim dosyasının içinde yazıp o dosyayı eklenti   olarak gönderirler veya akla gelmeyen bambaşka metodlar keşfederler. Bu teknik   savaş karşılıklı devam eder. Bu nedenle hiç bir spam tarayıcısı bu tür mesajları   yüzde yüz oranında filtreleyememektedir. </p>
<p>Sorunun çözümü, ülkelerin spam ile ilgili yasal düzenlemeler yapmasında   görünse de, kişilerin virüs ve spyware gibi zararlılardan kendilerini   korumaları, ücretsiz sitelere e-posta adreslerini verirken iki kere düşünmeleri   ve kaynağı belirsiz programları çalıştırmamaları da bir o kadar önem   taşımaktadır. </p>
<p><STRONG>Phıshıng</STRONG></p>
<p>Balık tutmak anlamına gelen "fishing" sözcüğünün bozulması ile   elde edilen bu sözcük, Internet üzerinde "balık" olarak gördükleri kullanıcılara   e-postalar atıp onları yönlendirerek menfaat sağlamaya çalışmak ya da zarar   vermek anlamında kullanılmaktadır. </p>
<p>Bu tür e-posta mesajları kullanıcıların bilgisizliklerinden yararlanarak   kendi kendilerine zarar vermelerini sağlamaya çalışırlar. Örneğin "Şu tarihte   filanca virüs tüm dünyada Internet üzerinden saldırıya geçecek. O tarihte sakın   bilgisayarlarınızı açmayın!" türünden bir mesaj olsa olsa sizi kendi rızanızla o   gün bilgisayar kullanımından mahrum etmekten başka bir işe yaramayacaktır. Ya   da, daha kötüsü, "Dikkat! Bilgisayarınızın Windows/System dizini altında   falanca.dll adında bir dosya görüyorsanız bilgisayarınıza filanca virüsü   bulaşmış demektir. Derhal o dosyayı silin ve bilgisayarınızı kapayıp açın!" gibi   bir e-posta, belki de sisteminiz için gerekli bir dosyayı size kendi ellerinizle   sildirterek bilgisayarınızı çalışmaz hale getirmeyi başarabilecektir. </p>
<p>Bunların dışında, unutulmamalıdır ki, bankalar başta olmak üzere hiç bir   ciddi kuruluş kişisel bilgilerinizi e-posta yoluyla almaya ya da değiştirmeye   kalkışmaz. E-Posta yazıp "kişisel bilgilerinizi değiştirmek için şuraya   tıklayın" demez. Teknik hilelerle e-posta''nın içinde tıklamanız istenen link,   sahiden de gerçek bankanın adresi gibi gösterilebilir. Ancak o link   tıklandığında aslında gerçek bankanın web sayfasının taklidi olan bambaşka bir   adrese yönlendirebilir ve kullanıcı bunu farketmez. Bu gibi durumlarda en iyi   yöntem, ilgili kurumu arayıp durumu doğrulatmaktır. </p>
<p>Kredi kartı numaraları, kişisel bilgiler, e-posta dahil her türlü şifre hiç   bir zaman e-posta ile açıkça yollanmamalıdır. Bir e-posta teknik olarak gideceği   yere varana kadar bir çok noktadan geçmektedir. Bu noktalarda e-postaların   içeriğinin "dinlenmesi" her zaman mümkündür. </p>
<p>Özellikle Kablosuz Internet''in kullanıldığı alanlarda mecbur kalınmadıkça   banka gibi yerlere girilmemeli, kredi kartı, şifre vs. ile ilgili işlemler   nereyle olursa olsun yapılmamalıdır. Havadaki sinyaller üçüncü şahıslar   tarafından dinlenebilir. Sinyaller şifreli dahi olsa unutulmamalıdır ki tüm   şifreleme yöntemleri sadece kırılıncaya kadar güvenlidir. </p>
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 53);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('spss-081118', 'tr', 'Öğrencilerimiz için IBM SPSS yazılımları', '<div class="icerik">

  <p>Üniversitemizin Değerli Öğrencileri,<br />
<br />
İstatistiksel analiz, veri ve metin madenciliği, tahmine dayalı modelleme, karar optimizasyonu, işbirliği ve devreye alma yazılımı olan IBM SPSS yazılımlarını öğrencilerimizin kullanımına sunmuş bulunmaktayız. IBM SPSS Statistics v23, AMOS v23, Sample Power v3, Visualization Designer v1.0 (Windows &amp; Mac) kurulum dosyaları ve kılavuzları yazılım depomuzdan temin edilebilmektedir. Ayrıntılı bilgi Yazılım Deposu IBM SPSS Yazılımları sayfasında mevcuttur. <br />
<br />
        
  Hacettepe Üniversitesi Bilgi İşlem Portalı (<a href="https://portal.hacettepe.edu.tr/" target="_blank">https://portal.hacettepe.edu.tr/</a>)<br />
  <br />
        
  Kullanıcı adı: E-posta kullanıcı adınız (@hacettepe.edu.tr eklemeyiniz)<br />
        
  Şifre: Mevcut eposta şifreniz<br />
  <br />
(Giriş yapıldıktan sonra sol menüden &quot;Akademik Yazılımlar &gt; IBM SPSS Yazılımları&quot;)<br />
<br />
Bilginize sunulur. Saygılarımızla. <br />
<br />
Bilgi İşlem Daire Başkanlığı<p>

   
</div>', 'Hacettepe Üniversitesi Bilgi İşlem Daire Başkanlığı', '', '', 54);
INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('faq', 'tr', 'Sık Sorulan Sorular', '<div class="icerik">

  
  


  
   <div class="container"> 
		<div class="panel-group" id="accordion">
<p style=''color:red;font-weight: bold;font-size: 20px;''>E-POSTA HİZMETİ</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse1">Üniversite mensubuyum elektronik posta hesabı nasıl alabilirim?</a>

        </p>

      </div>

    
      <div id="collapse1" class="panel-collapse collapse">

        <div class="panel-body"><a href="/tr/email-account">Detaylı bilgi için tıklayınız</a></div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse2">Bölüm/ anabilim dalı / fakülte / sempozyum / kongre vb. için kullanılmak üzere elektronik posta hesabı nasıl alabilirim?</a>

        </p>

      </div>

    
      <div id="collapse2" class="panel-collapse collapse">

        <div class="panel-body">Hacettepe Üniversitesi bünyesinde, fakülte, enstitü, bölüm, birim, üniversite ile ilgili bir topluluk, proje grubu, organizasyon vb. bir oluşum için ayrı bir e-posta hesabı almak mümkündür. Bunun için bağlı bulunduğunuz makamın (dekan, bölüm başkanı, müdürlük, vb.) yönetiminden dairemize yazılı bir istekte bulunulması gerekmektedir. Kurumsal Elektronik Posta Talep Formu doldurularak yazıya eklenmelidir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse3">Adıma tanımlanan elektronik posta hesabını ne için kullanabilirim?</a>

        </p>

      </div>

    
      <div id="collapse3" class="panel-collapse collapse">

        <div class="panel-body">
<ol>
<li>İletişim için,</li>
<li>Kampüs içinde kablosuz ağlara bağlanmak için,</li>
<li>Kampüs dışından Kütüphane Kaynaklarına erişim için,</li>
<li>Yurt başvurusu yapmak için,</li>
<li>Yönetim Sistemlerine (Akademik ve İdari Personel) giriş işlemi için kullanabilirsiniz.</li>
</ol>
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse4">Elektronik posta hesabımın şifresini unuttum, nasıl alabilirim?</a>

        </p>

      </div>

    
      <div id="collapse4" class="panel-collapse collapse">

        <div class="panel-body">
<a href="portal.hacettepe.edu.tr" target="_blank">portal.hacettepe.edu.tr</a> adresinden "E-posta İşlemleri" menüsünden "Şifremi Unuttum" butonunu kullanarak geçici şifrenizi alabilirsiniz.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse5">Elektronik posta hesabımın kullanıcı adını unuttum nasıl öğrenebilirim? </a>

        </p>

      </div>

    
      <div id="collapse5" class="panel-collapse collapse">

        <div class="panel-body">Kullanıcı adınızı, Bilgi İşlem Daire Başkanlığı Portalından “Kullanıcı Adımı Unuttum” butonunu kullanarak öğrenmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse6">Elektronik posta hesabımın şifresini ne kadar kullanabilirim?</a>

        </p>

      </div>

    
      <div id="collapse6" class="panel-collapse collapse">

        <div class="panel-body">
Güvenlik nedeniyle tarafınıza tanımlanan şifreyi 180 gün kullanabilmektesiniz. Bu nedenle şifrenizin kullanıma kapanmaması için 180 gün de bir güncellemeniz gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse7">Elektronik posta hesabımın şifresini nasıl değiştirebilirim / güncelleyebilirim?</a>

        </p>

      </div>

    
      <div id="collapse7" class="panel-collapse collapse">

        <div class="panel-body">
Bilgi İşlem Daire Başkanlığı Portalından “Şifre Güncelleme” butonunu kullanarak şifrenizi güncellemeniz gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse8">Elektronik posta hesabımın şifresini değiştirirken nelere dikkat etmem gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse8" class="panel-collapse collapse">

        <div class="panel-body">
<ol>
<li>Seçeceğiniz parola en az 8, en fazla 15 karakter olmalıdır.</li>
<li>Seçeceğiniz parola içerisinde bir büyük harf, bir küçük harf, bir rakam ve bir özel karakter (~!@#?$%^&()_- ) mutlaka olmalıdır.</li>
<li>Seçeceğiniz parola, teknik sınırlamalar nedeniyle (ı,İ,ğ,Ğ,ş,Ş,ü,Ü,ö,Ö,ç,Ç) harflerini içermemelidir.</li>
</ol>
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse9">Elektronik posta hesabımın kullanıcı adı ve şifresi ile BİLSİS kullanıcı adı ve şifrem aynı mıdır?</a>

        </p>

      </div>

    
      <div id="collapse9" class="panel-collapse collapse">

        <div class="panel-body">
Adınıza tanımlanan @hacettepe.edu.tr uzantılı elektronik posta hesabının kullanıcı adı ve şifresi BİLSİS şifrenizden farklıdır. Öğrenci Bilgi Sistemi (BİLSİS) için kullanıcı adı ve şifre Öğrenci İşleri Dairesi Başkanlığının Bilgi Sistemleri Müdürlüğü tarafından verilmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse10">Bilgi İşlem Daire Başkanlığı portal ekranından şifre alamıyorum, ne yapmam gerekir?</a>

        </p>

      </div>

    
      <div id="collapse10" class="panel-collapse collapse">

        <div class="panel-body">
Bilgi İşlem Daire Başkanlığı portal ekranından şifre alabilmeniz için daha önceden bilgi güncellemesi yapmış olmanız gerekmektedir. Şifrenizi unutmanız halinde veya şifrenizin bloke olması halinde bilgi güncellemesi yapamayacağınız için bu tür durumlarda Çağrı Merkezi ile iletişime geçerek "Bilgi Güncellemesi" yaptırmanız gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse11">Elektronik posta hesabımı mezun olduktan veya üniversiteden ayrıldıktan sonra kullanabiliyor muyum?</a>

        </p>

      </div>

    
      <div id="collapse11" class="panel-collapse collapse">

        <div class="panel-body">
Elektronik posta hesabınız, Mezun olmanız veya Üniversitemiz ile ilişiğinizin kesilmesi durumunda Elektronik Posta Yönergesi ile belirlenen süre içinde kullanıma kapatılmaktadır.
Mezun hesabı almak isteyen mezunlarımız, Bilgi İşlem Daire Başkanlığı Portalından "Yeni Hesap Açma (Mezun Hesabı)" butonunu kullanarak kurumsal elektronik posta hesabı alabilir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse12">Elektronik posta hesabından mail aktarımı nasıl yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse12" class="panel-collapse collapse">

        <div class="panel-body">
<a href="/tr/email-migration" target="_blank"> https://bidb.hacettepe.edu.tr/tr/eposta_gecis </a> bağlantı adresindeki ilgili yönergeleri izleyerek hesabınızı posta istemcisine kurmanız gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse13">Elektronik posta hesabımın kapatılması için ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse13" class="panel-collapse collapse">

        <div class="panel-body">
Ana sayfamızda yer alan "Formlar" başlığı altında yer alan <A href="/dosyalar/BGYS-F-12e-PostaiptalFormu.docx">E-posta İptal Formu</A> nu doldurup imzaladıktan sonra Çağrı Merkezine iletmeniz gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse14">Elektronik posta hesabımın kullanıcı adını değiştirmek için (zorunlu sebepler dahilinde) ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse14" class="panel-collapse collapse">

        <div class="panel-body">
Adınıza tanımlanan hesabın kullanıcı adı değişikliği ancak hesap kapatılıp yeni hesap açılarak değiştirilebilmektedir. Bunun için kullanıcının “E-posta İptal Formu”nu doldurarak Çağrı Merkezine şahsen veya mail yoluyla başvurması gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse15">Haberleşme listesi oluşturmak mümkün müdür?</a>

        </p>

      </div>

    
      <div id="collapse15" class="panel-collapse collapse">

        <div class="panel-body">
Mümkün ancak istediğiniz adres ile ilgili bölümümüze resmi yazı ile başvurmanız gerekmektedir. 
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse16">Haberleşme listesine erişim ve kullanım nasıl yapılabilir?</a>

        </p>

      </div>

    
      <div id="collapse16" class="panel-collapse collapse">

        <div class="panel-body">
<a href="/dosyalar/haberlesme101023.pdf" " target="_blank">haberlesme</a> linkine basarak dokümanı inceleyebilirsiniz.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse17">Yanlışlıkla maillerim silindi ne yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse17" class="panel-collapse collapse">

        <div class="panel-body">
<a href="/dosyalar/e-postakurtarma101023.pdf" target="_blank">e-posta kurtarma</a> linkinden gerekli dokümana ulaşabilirsiniz.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse18">SUN-JAVA ara yüzünden hesabıma giriş yaptığımda inbox klasörüm görünmüyor neden?</a>

        </p>

      </div>

    
      <div id="collapse18" class="panel-collapse collapse">

        <div class="panel-body">
Kullanıcı adı ve şifrenizle ara yüze giriş yaptığınızda inbox klasörünüzü göremiyorsanız, hesabınız spam mail yaydığı için sistem tarafından otomatik olarak engellenmiştir. Böyle bir durumda <a href="portal.hacettepe.edu.tr">portal.hacettepe.edu.tr</a> adresinde  "E-posta İşlemleri" menüsünde yer alan "Proxy-Spam kontrol" butonunu kullanarak engeliniz kaldırmanız ve şifrenizi güvenlik nedeniyle değiştirmeniz gerekmektedir.
<br>Engeli kaldıramamanız halinde Çağrı Merkezi ile iletişime geçmeniz gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse19">Bulut depolama alanı için belirlenen kota nedir? Arttırmak için ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse19" class="panel-collapse collapse">

        <div class="panel-body">Her kullanıcıya 1 TB Onedrive bulut alanı verilmektedir. Bu alan arttırılamamaktadır.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse20">Sistem(ler) üzerinde dışarıdan bağlantı yapmak ve sunuculara erişim için ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse20" class="panel-collapse collapse">

        <div class="panel-body">VPN bağlantısı yaparak kampüs dışından erişim sağlanabilmektedir. Bunun için dairemize yazılı bir istekte bulunulması gerekmektedir. VPN Bağlantı Talep Formu doldurularak yazıya eklenmelidir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>EBYS</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse21">Yeni Elektronik Belge Yönetim Sistemini (EBYS)</a>

        </p>

      </div>

    
      <div id="collapse21" class="panel-collapse collapse">

        <div class="panel-body">
Yeni EBYS kurulum, oturum açma, belge oluşturma, ıslak imzalı iş süreçleri, e-imza
kurulum ve kullanımı, yardım bilgileri, sorun yaşanınca başvurulacak sorumlulara ait
iletişim bilgileri için <a href="http://www.ebysbilgilendirme.hacettepe.edu.tr" target="_blank">http://www.ebysbilgilendirme.hacettepe.edu.tr</a> adresi
kullanılmalıdır.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>PROXY</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse22">Proxy hizmeti nedir?</a>

        </p>

      </div>

    
      <div id="collapse22" class="panel-collapse collapse">

        <div class="panel-body">
Proxy, internet üzerindeki bir bilgisayar ile internete bağlı diğer bilgisayarlar arasındaki iletişimi sağlayan yardımcı bir geçiş yolu sistemidir. Bir Proxy sunucusu, sizden aldığı istekleri yürütür ve sonucu yine size iletir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse23">Kütüphane kaynaklarına kampüs dışından nasıl erişim sağlayabilirim?</a>

        </p>

      </div>

    
      <div id="collapse23" class="panel-collapse collapse">

        <div class="panel-body">
Sadece Hacettepe Üniversitesi mensupları elektronik kaynaklara uzaktan erişim sağlayabilirler. Bunun için @hacettepe.edu.tr uzantılı elektronik posta hesabı almış olmanız ve cihazınıza gerekli Proxy ayarlarını yapmış olmanı gerekmektedir.
<br>Proxy Ayarları için <a href="/tr/proxy" target="_blank"> https://bidb.hacettepe.edu.tr/tr/proxy </a>adresini kullanabilirsiniz.


</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse24">Proxy ayarlarını eksiksiz yapmama ve kullanıcı adımı, şifremi doğru girmeme rağmen, sürekli olarak aynı ekran karşıma geliyor, ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse24" class="panel-collapse collapse">

        <div class="panel-body">Proxy ayarlarını yapmanıza ve kullanıcı adı şifrenizi girmenize rağmen bağlantı kuramamanız, hesabınızın sistem tarafından otomatik olarak engellendiğini göstermektedir. Engelin kaldırabilmesi için Çağrı Merkezi ile iletişime geçmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>İNTERNET</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse25">Kampüs içinde kablosuz ağlara nasıl bağlanabilirim?</a>

        </p>

      </div>

    
      <div id="collapse25" class="panel-collapse collapse">

        <div class="panel-body">Üniversitemiz mensubu tüm akademik/idari personel ve öğrencilerimiz kampüslerimizde HACETTEPE ve EDUROAM ağlarına bağlanabilmektedir. Bunun için @hacettepe.edu.tr uzantılı elektronik posta hesabına sahip olmaları gerekmektedir.
HACETTEPE ağına bağlanabilmek için ara yüze kullanıcı adı ve şifrenin yazılması yeterlidir. 
EDUROAM ağına bağlanabilmek için <a href="https://eduroam.hacettepe.edu.tr/" target="_blank">https://eduroam.hacettepe.edu.tr</a> internet adresini ziyaret etmek gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse26">Kablosuz ağlara neden bağlanamıyorum?</a>

        </p>

      </div>

    
      <div id="collapse26" class="panel-collapse collapse">

        <div class="panel-body">
Aşağıdaki nedenlerden dolayı kablosuz ağlara bağlanamıyor olabilirsiniz. 
<ol>
<li>Şifrenizin süresi dolmuş olabilir.</li>
<li>Cihaz için yapılan ayarlar sıfırlanmış olabilir.</li>
<li>Cihazın sürümünün güncellenmesi gerekebilir.</li>
<li>Cihazın daha önce bağlanmış olduğu kablosuz ağların unutturulması gerekebilir.</li>
</ol>
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse27">Kablolu internete bağlanamıyorum ne yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse27" class="panel-collapse collapse">

        <div class="panel-body">Detaylı bilgi ve yardım için 0.312 297 62 62 telefon numarasından Çağrı Merkezi ile iletişime geçmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse28">İnternet prizi çekilmesi için ne yapa bilirim?</a>

        </p>

      </div>

    
      <div id="collapse28" class="panel-collapse collapse">

        <div class="panel-body">İnternet prizi çekilmesi işlemi için Yapı İşleri Dairesi Başkanlığı ile iletişime geçilmeli, işlem bittikten sonra Çağrı Merkezine hattın açılması için bilgi verilmesi gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse29">Network kablosu ihtiyacımızı nasıl karşılaya biliriz?</a>

        </p>

      </div>

    
      <div id="collapse29" class="panel-collapse collapse">

        <div class="panel-body">Sorun Bildirim Destek Sisteminden ne kadar kabloya ihtiyaç duyulduğu ile ilgili bilgi verilmesi halinde Network birimi tarafından yardımcı olunmaktadır.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>WEB SERVİSİ</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse30">Bölüm/ anabilim dalı / fakülte / sempozyum / kongre vb. için kullanılmak üzere web alanı nasıl alabilirim?</a>

        </p>

      </div>

    
      <div id="collapse30" class="panel-collapse collapse">

        <div class="panel-body">Hacettepe Üniversitesi bünyesinde, fakülte, enstitü, bölüm, birim, üniversite ile ilgili bir topluluk, proje grubu, organizasyon vb. bir oluşum için web alanı almak mümkündür. Bunun için bağlı bulunduğunuz makamın (dekan, bölüm başkanı, müdürlük, vb.) yönetiminden dairemize yazılı bir istekte bulunulması gerekmektedir. Web Kullanıcı Kodu Talep Formu doldurularak yazıya eklenmelidir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse31">Hacettepe Üniversitesi internet sayfasında yer alması istenilen bilgiler, yapılması gereken düzeltmeler ve eklentiler için ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse31" class="panel-collapse collapse">

        <div class="panel-body">Sitede yer alması istenilen bilgiler, yapılması gereken düzeltmeler ve eklentiler için <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> adresine başvurulması gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse32">Kişisel web sayfası almak için ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse32" class="panel-collapse collapse">

        <div class="panel-body">Hacettepe Üniversitesi elektronik posta hesabı alan tüm Üniversite mensuplarımızın kişisel web alanları hesabı açtırdıkları zaman tanımlanmaktadır. Web sayfalarınızı oluşturan dosyalar kişisel web sayfanızı taşıyan sunucuda FTP ile açacağınız public_html klasörü içerisinde yer almaktadır. Giriş sayfanızın (açılış sayfanızın) ismi index (.html, .htm, .php... gibi) olmalıdır. Web sayfanızı herhangi bir tarayıcı yardımı ile http://yunus.hacettepe.edu.tr/~kullanıcıadı adresinden görüntülemeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse33">FTP yaparken sorun yaşıyorum sebebi ne olabilir?</a>

        </p>

      </div>

    
      <div id="collapse33" class="panel-collapse collapse">

        <div class="panel-body">Web sayfalarınızı oluşturan dosyalar kişisel web sayfanızı taşıyan sunucuda FTP ile açacağınız public_html klasörü içerisinde yer aldığından dolayı klasörünüz oluşturulmamış olabilir. 
<br>Şifrenizin süresi dolmuş olabilir.
<br>Hatalı kullanıcı yada şifre giriyor olabilirsiniz. Böyle bir durumda <a href="mailto:bidb@hacettepe.edu.tr">bidb@hacettepe.edu.tr</a> adresine mail göndermeniz veya Çağrı Merkezi ile iletişim kurmanız gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse34">MYSQL kullanabiliyor muyum, ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse34" class="panel-collapse collapse">

        <div class="panel-body">Tüm kullanıcılarımızın mysql kullanım hakkı bulunmaktadır. Mysql kullanmak isteyen kullanıcılarımız veri tabanını istemlerini <a href="mailto:webmaster@hacettepe.edu.tr">webmaster@hacettepe.edu.tr</a> e-posta yolu ile bildirmeleri gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse35">İçerik Yönetim Sistemi nedir? Kimler kullanabilir?</a>

        </p>

      </div>

    
      <div id="collapse35" class="panel-collapse collapse">

        <div class="panel-body">
HÜ-İYS, merkezi olarak web  sayfalarınızın içeriğini yönetebileceğiniz web tabanlı bir uygulamadır. Bu  uygulama ile web sitenize içerik girişi ve içerik düzenlemesi yapabilirsiniz.  Bu düzenlemeleri yaparken herhangi bir programa ihtiyaç duymadan tarayıcınız  üzerinden işlemlerinizi yapabilirsiniz.<br>
  HÜ-İYS aşağıdaki birimler tarafından  kullanılabilir.
<ul>
  <li>Fakülteler</li>
  <li>Bölümler</li>
  <li>Birimler</li>
  <li>Araştırma  Merkezleri</li>
  <li>Enstitüler</li>
  <li>Yüksek Okullar</li>
  <li>Meslek Yüksek  Okulları</li>
  <li>Öğrenci  Toplulukları</li>
  <li>Hacettepe  Üniversitesi Tarafından Düzenlenen Kongreler</li>
</ul>
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>E-İMZA</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse36">Elektronik imzaya nasıl başvurabilirim?</a>

        </p>

      </div>

    
      <div id="collapse36" class="panel-collapse collapse">

        <div class="panel-body">Elektronik imza ile ilgili her türlü  bilgi ve yardım için E-imza Kullanma Rehberini (<a href="https://bidb.hacettepe.edu.tr/eimza/basvuru.php">https://bidb.hacettepe.edu.tr/eimza/basvuru.php</a>) ziyaret etmeniz veya <a href="mailto:eimza@hacettepe.edu.tr">eimza@hacettepe.edu.tr</a> adresine mail göndermeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>HUYS</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse37">Yönetim Sistemlerine neden giriş yapamıyorum?</a>

        </p>

      </div>

    
      <div id="collapse37" class="panel-collapse collapse">

        <div class="panel-body">Üniversitemiz akademik ve idari personelin sisteme giriş yapabilmesi için @hacettepe.edu.tr uzantılı elektronik posta hesabının olması gerekmektedir. Tanımlanan hesabın kullanıcı adı ve şifresi ile giriş yapıldığı için şifrenizin aktif olması, kullanıcı adınızı yazarken @hacettepe.edu.tr uzantısını yazmamanız gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse38">Yönetim Sistemlerine giriş yapabiliyorum ama Bireysel İşlemlere tıkladığımda yetkiniz yok uyarısı alıyorum, ne yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse38" class="panel-collapse collapse">

        <div class="panel-body">Kullanıcı adı ve şifrenizle sorunsuz bir şekilde sisteme giriş yapabildiğiniz halde “Bireysel İşlemler”e tıklandığında “yetkiniz yok” uyarı alıyorsanız, hesabınız için gerekli rol tanımlanması yapılmamış olabilir. Sorunun giderilmesi için Başkanlığımızı arayarak biriminizden sorumlu kişi ile iletişime geçmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>UYGULAMA VE PROGRAMLAR</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse39">SPSS uygulamasını MAC bilgisayarımda kullanabilir miyim? </a>

        </p>

      </div>

    
      <div id="collapse39" class="panel-collapse collapse">

        <div class="panel-body">El Capitan sürümünden sonraki sürümlerde spss çalışmamaktadır. Tavsiyemiz kullanıcıların spss v23 için Windows 10 işletim sistemini kullanmalarıdır.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse40">Üniversitemiz eğitim amaçlı uygulamaları ücretsiz olarak sunmakta mıdır? </a>

        </p>

      </div>

    
      <div id="collapse40" class="panel-collapse collapse">

        <div class="panel-body">Evet üniversitemiz eğitim amaçlı olarak birçok uygulamayı sunmaktadır. Bu uygulamalara, yazilimdeposu.hacettepe.edu.tr adresinden ulaşabilirsiniz. Uygulamaları sorunsuz kullanabilmek için uygulamayı yazilimdeposu.hacettepe.edu.tr adresinden indiriniz. Sayfadaki kurulum dokümanlarını okuyup oradaki adımları takip ediniz. Aksi halde lisans sorunları yaşayabilirsiniz.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse41">Eset Endpoint uygulaması Lisans/Güncelleme uyarısı veriyor. Ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse41" class="panel-collapse collapse">

        <div class="panel-body">Eset uygulamasını bilgisayarınızdan kaldırıp güncel uygulamayı yazilimdeposu.hacettepe.edu.tr den indirip bilgisayarınıza yükleyiniz. Uygulamayı bilgisayarınızdan kaldırırken Eset Management Agent’in de kaldırıldığından emin olunuz.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse42">Office365 uygulamalarını kullanmak için ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse42" class="panel-collapse collapse">

        <div class="panel-body"><a href="/tr/office365" target="_blank">https://bidb.hacettepe.edu.tr/tr/office365</a> adresi üzerinden tüm detaylara ulaşabilirsiniz.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse43">Office365 uygulamasını kullanmaya çalıştığımda lisans uyarısı alıyorum. Ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse43" class="panel-collapse collapse">

        <div class="panel-body">bidb@hacettepe.edu.tr eposta adresine durumu detaylı anlatır şekilde e-posta atınız. Sadece hacettepe uzantılı adresinizden attığınız e-postalara dönüş yapılacaktır.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse44">Bilgisayarımdaki office uygulamasına hacettepe hesabımla giriş yaptığımda lisans hatası alıyorum ne yapmalıyım?</a>

        </p>

      </div>

    
      <div id="collapse44" class="panel-collapse collapse">

        <div class="panel-body">Office uygulamasını hacettepe hesabınızla sorunsuz kullanabilmek için, office.com dan office365 uygulamasını bilgisayarınıza indirip, bu uygulamayı kullanmalısınız. Detaylı bilgi için aşağıdaki linkteki talimatları inceleyiniz.
<a href="/tr/office365" target="_blank"> https://bidb.hacettepe.edu.tr/tr/office365</a>
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	<p style=''color:red;font-weight: bold;font-size: 20px;''>DİĞER</p>
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse45">Windows/Office etkinleştirmesini (aktivasyonunu) yaparken hata alıyorum, ne yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse45" class="panel-collapse collapse">

        <div class="panel-body">Aldığınız hata kodunu Çağrı Merkezine bildirmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse46">Bilgisayarımda oluşan donanımsal arızalar için ne yapa bilirim?</a>

        </p>

      </div>

    
      <div id="collapse46" class="panel-collapse collapse">

        <div class="panel-body">Bilgi İşlem Daire Başkanlığı Sorun Bildirim Destek Sistemini (<a href="https://bidbdestek.hacettepe.edu.tr">https://bidbdestek.hacettepe.edu.tr</a>) kullanarak, barkodlu bilgisayarınız için destek almanız gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse47">Ağ yazıcısından çıktı alınamıyor, ne yapa bilirim?</a>

        </p>

      </div>

    
      <div id="collapse47" class="panel-collapse collapse">

        <div class="panel-body">Bilgi İşlem Daire Başkanlığı Sorun Bildirim Destek Sisteminden (<a href="https://bidbdestek.hacettepe.edu.tr">https://bidbdestek.hacettepe.edu.tr</a>) bildirimde bulunmanız gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse48">Yurt başvurusu nasıl yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse48" class="panel-collapse collapse">

        <div class="panel-body">Yurt başvuru işlemleri için Sağlık, Kültür ve Spor Daire Başkanlığının “Barınma Olanakları” sayfasının ziyaret edilmesi gerekmektedir. <a href="https://sksdb.hacettepe.edu.tr/bidbnew/category.php?id=3&title=barinma" target="_blank">https://sksdb.hacettepe.edu.tr/bidbnew/category.php?id=3&title=barinma</a></div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse49">E-Öğrenme platformuna (Blackboard Uzaktan Eğitim Sistemi) giriş yapmak için ne yapmam gerekiyor?</a>

        </p>

      </div>

    
      <div id="collapse49" class="panel-collapse collapse">

        <div class="panel-body">Ön Lisans ve Lisans öğrencileri<br>
<a href="https://hadi.hacettepe.edu.tr" target="_blank">https://hadi.hacettepe.edu.tr</a>
<br>
Yabancı Dil Hazırlık öğrencileri ve YDYO Kurs öğrencileri<br>
<a href="https://ydyohazirlik.hacettepe.edu.tr" target="_blank">https://ydyohazirlik.hacettepe.edu.tr</a>
<br>
Tıp Fakültesi öğrencileri,<br>
<a href="https://tipmoodle.hacettepe.edu.tr" target="_blank">https://tipmoodle.hacettepe.edu.tr</a>
<br>
Tezli ve Tezsiz Lisansüstü öğrencileri;<br>
<a href="https://lisansustu.hacettepe.edu.tr" target="_blank">https://lisansustu.hacettepe.edu.tr</a>
<br>
üzerinden giriş yapmaları gerekmektedir.<br>
Detaylı bilgi ve yardım için Uzaktan Eğitim Uygulama ve Araştırma Merkezi ile iletişime geçilmesi gerekmektedir.
</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse50">Hacettepe Üniversitesi kimlik kartımı nasıl alabilirim?</a>

        </p>

      </div>

    
      <div id="collapse50" class="panel-collapse collapse">

        <div class="panel-body">Sağlık, Kültür ve Spor Daire Başkanlığına APK birimine HÜ-KART için başvurmanız gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse51">Üniversite mensubuyum yazılım deposunu kullanabiliyor muyum?</a>

        </p>

      </div>

    
      <div id="collapse51" class="panel-collapse collapse">

        <div class="panel-body">Hacettepe Üniversitesi elektronik posta hesabı alan tüm Üniversite mensuplarımız yazılım deposunu kullanabilmektedir. Ücretsiz olarak lisanslı yazılımlara erişim sağlayabilmektedirler.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse52">Yazılım deposuna nasıl giriş yapabilirim?</a>

        </p>

      </div>

    
      <div id="collapse52" class="panel-collapse collapse">

        <div class="panel-body">Hacettepe Üniversitesi elektronik posta hesabınızın kullanıcı adı ve şifresi ile @hacettepe.edu.tr uzantısı olmadan giriş yapmanız gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

        <p class="panel-title">

          <a data-toggle="collapse" data-parent="#accordion" href="#collapse53">BİLSİS sistemine giriş yapamıyorum, ne yapmam gerekir?</a>

        </p>

      </div>

    
      <div id="collapse53" class="panel-collapse collapse">

        <div class="panel-body">0.312 297 65 70 (5 Hat) Beytepe / 0.312 305 21 41 Sıhhiye telefon numaralarından veya hureg@hacettepe.edu.tr e-posta adresinden Öğrenci İşleri Dairesi Başkanlığı Bilgi Sistemleri Müdürlüğü ile iletişime geçmeniz gerekmektedir.
<br>BİLSİS şifresi kayıtlı e-postama gelmiyor, ne yapabilirim?
<br>0.312 297 65 70 (5 Hat) Beytepe / 0.312 305 21 41 Sıhhiye telefon numaralarından veya hureg@hacettepe.edu.tr e-posta adresinden Öğrenci İşleri Dairesi Başkanlığı Bilgi Sistemleri Müdürlüğü ile iletişime geçmeniz gerekmektedir.</div>

		<p>&nbsp;</p>
      </div>

    </div>

	
	<div class="panel panel-default">

      <div class="panel-heading">

