INSERT INTO sayfa (slug, dil, baslik, icerik_html, seo_title, seo_description, seo_keywords, sira) VALUES ('stylecc50-removal', 'tr', '50. yıl logolarının web sayfasından kaldırılması hakkında', '<div class="icerik">
<p>Hacettepe  Üniversitesi''nin kuruluşunun 50.yılı nedeniyle Hacettepe Üniversitesi logosuna  eklenen 50.yıl logoları 50.yılın sona ermesi nedeniyle web sayfalarından  kaldırılmaktadır.</p>
<p>50.yıl  logosunu kaldırmak için Hacettepe Üniversitesi birimlerince kullanılan  tasarımda style.css dosyasında yapılması gereken değişiklikler aşağıdaki  gibidir.<br>
(style.css son haline <a href="/sablon2017/css/style.css" target="_blank">http://www.bidb.hacettepe.edu.tr/sablon2017/css/style.css</a> adresinden ulaşabilirsiniz.)</p>
<p>1-  banner50 ve banner50_en classlarında width 10px yapılıp background  kapatılmalıdır.<br>
  2-  banner ve banner_en classlarında width 930px yapılmalıdır</p>
<p>Düzenlenmiş  classlar aşağıdaki gibidir.<br>
</p>
<p>#banner50{<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  width:10px;<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  height:100px;<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  /*background:url(../images/banner50.png) no-repeat left center;*/<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  float:left;<br>
  }<br>
  #banner50_en{<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  width:10px;<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  height:100px;<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  /*background:url(../images/banner50_en.png) no-repeat left center;*/<br>
  &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;  float:left;<br>
  }<br>
  #banner{<br>
